        walls.add(new Wall(ox, oy, ox + pw, oy, 6.5));
        walls.add(new Wall(ox + pw, oy, ox + pw, oy + ph, 6.5));
        walls.add(new Wall(ox + pw, oy + ph, ox, oy + ph, 6.5));
        walls.add(new Wall(ox, oy + ph, ox, oy, 6.5));

        // Partitions 4.5"
        double midY = oy + 18.0 * FT_PX;
