        CADElement wBed2Cot = new CADElement("window", "Bed 2 Egress 3'×5'", ox + pw - 1.75 * FT_PX, midY + 3.0 * FT_PX - 0.27 * FT_PX, 3.5 * FT_PX, 0.54 * FT_PX);
        wBed2Cot.rotation = 90;
