    /**
     * Core Parametric Room Placement Logic:
     * Calculates clean insertion offset next to existing layout or at center,
     * creates 4 perimeter walls, auto-joins corners, and inserts door, window, tag, and dimensions.
     */
    public void generateParametricRoom(String name, double wFt, double hFt, double thick,
                                       int doorPos, int winPos, boolean addTag, boolean addDims) {
        saveUndoState();

        // Calculate placement origin: if empty, place at 120, 120. Else place to right or below existing bounding box
        double ox = 120.0, oy = 120.0;
        if (!walls.isEmpty()) {
            double maxX = -Double.MAX_VALUE;
            double minY = Double.MAX_VALUE;
            for (Wall w : walls) {
                maxX = Math.max(maxX, Math.max(w.x1, w.x2));
                minY = Math.min(minY, Math.min(w.y1, w.y2));
            }
            ox = maxX + 4.0 * FT_PX; // 4 ft spacing from last wall
            oy = minY;
        }

        double pw = wFt * FT_PX;
        double ph = hFt * FT_PX;

        // 1. Create 4 Perimeter Walls
        Wall topW = new Wall(ox, oy, ox + pw, oy, thick);
        Wall rightW = new Wall(ox + pw, oy, ox + pw, oy + ph, thick);
        Wall bottomW = new Wall(ox + pw, oy + ph, ox, oy + ph, thick);
        Wall leftW = new Wall(ox, oy + ph, ox, oy, thick);

        walls.add(topW);
        walls.add(rightW);
        walls.add(bottomW);
        walls.add(leftW);

        // 2. Door Placement (3'-0" standard door, 2'-6" for bath/powder)
        boolean isBath = name.toLowerCase().contains("bath") || name.toLowerCase().contains("powder") || name.toLowerCase().contains("toilet");
        double doorW = isBath ? 2.5 * FT_PX : 3.0 * FT_PX;
        double doorH = (thick / 12.0) * FT_PX;
        String doorName = name + " Door " + (isBath ? "2'-6\"" : "3'-0\"");

        if (doorPos == 0) { // South Wall (Bottom) - swings inward (upward into room)
            CADElement d = new CADElement("door", doorName, ox + pw * 0.2, oy + ph - doorH / 2.0, doorW, doorH);
            elements.add(d);
        } else if (doorPos == 1) { // North Wall (Top) - swings inward (downward into room)
            CADElement d = new CADElement("door", doorName, ox + pw * 0.2, oy - doorH / 2.0, doorW, doorH);
            d.flipV = true;
            elements.add(d);
        } else if (doorPos == 2) { // East Wall (Right) - swings inward (leftward into room)
            CADElement d = new CADElement("door", doorName, ox + pw - doorH / 2.0, oy + ph * 0.2, doorH, doorW);
            d.rotation = 90;
            elements.add(d);
        } else if (doorPos == 3) { // West Wall (Left) - swings inward (rightward into room)
            CADElement d = new CADElement("door", doorName, ox - doorH / 2.0, oy + ph * 0.2, doorH, doorW);
            d.rotation = 90;
            d.flipH = true;
            elements.add(d);
        }

        // 3. Window Placement (4'-0" standard window, 2'-0" vent for bath)
        double winW = isBath ? 2.0 * FT_PX : 4.0 * FT_PX;
        double winH = (thick / 12.0) * FT_PX;
        String winType = isBath ? "window-vent" : "window";
        String winName = name + " Window " + (isBath ? "2'-0\" Vent" : "4'-0\"");

        if (winPos == 0) { // North Wall (Top)
            elements.add(new CADElement(winType, winName, ox + (pw - winW) / 2.0, oy - winH / 2.0, winW, winH));
        } else if (winPos == 1) { // East Wall (Right)
            CADElement w = new CADElement(winType, winName, ox + pw - winH / 2.0, oy + (ph - winW) / 2.0, winH, winW);
            w.rotation = 90;
            elements.add(w);
        } else if (winPos == 2) { // West Wall (Left)
            CADElement w = new CADElement(winType, winName, ox - winH / 2.0, oy + (ph - winW) / 2.0, winH, winW);
            w.rotation = 90;
            elements.add(w);
        } else if (winPos == 3) { // South Wall (Bottom)
            elements.add(new CADElement(winType, winName, ox + (pw - winW) / 2.0, oy + ph - winH / 2.0, winW, winH));
        }

        // 4. Room Area Tag
        if (addTag) {
            String tagText = name + "\n" + (int) wFt + "'-0\" × " + (int) hFt + "'-0\"";
            double tagW = Math.min(pw * 0.8, 12.0 * FT_PX);
            double tagH = 3.5 * FT_PX;
            elements.add(new CADElement("tag", tagText, ox + (pw - tagW) / 2.0, oy + (ph - tagH) / 2.0, tagW, tagH));
        }

        // 5. Exterior Linear Dimensions
        if (addDims) {
            dimensions.add(new CADDimension(ox, oy, ox + pw, oy, -28.0)); // Top dimension
            dimensions.add(new CADDimension(ox + pw, oy, ox + pw, oy + ph, -28.0)); // Right dimension
        }

        autoJoinAllWalls();
        checkAllCollisions();

        // Auto-select all newly generated elements so the user gets instant feedback with grips & selection outline
        clearSelection();
        addToSelection(topW);
        addToSelection(rightW);
        addToSelection(bottomW);
        addToSelection(leftW);
        currentTool = ToolMode.SELECT;
        selectToolButton(ToolMode.SELECT);

        markProjectDirty(true);
        updateProperties();
        viewportPanel.zoomToFit();
    }

    /**
     * Structural Column Grid Generator Dialog:
     * Calculates column locations at wall intersections, corners, and long spans
     * (e.g. 10' to 15' structural bay spans) according to standard RCC construction practice.
     */
    public void showStructuralGridDialog() {
        JDialog dlg = new JDialog(this, "Structural Column Grid Generator", true);
        dlg.setLayout(new BorderLayout());
        dlg.getContentPane().setBackground(new Color(15, 23, 42));

        JPanel form = new JPanel(new GridBagLayout());
        form.setOpaque(false);
        form.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(new Color(30, 41, 59)),
                new EmptyBorder(16, 20, 16, 20)));
        GridBagConstraints g = new GridBagConstraints();
        g.fill = GridBagConstraints.HORIZONTAL;
        g.insets = new Insets(6, 6, 6, 6);

        // Header
        JLabel titleLbl = new JLabel("STRUCTURAL COLUMN GRID GENERATOR");
        titleLbl.setFont(new Font("Segoe UI", Font.BOLD, 15));
        titleLbl.setForeground(Color.WHITE);
        g.gridx = 0; g.gridy = 0; g.gridwidth = 2;
        form.add(titleLbl, g);

        JLabel subLbl = new JLabel("Auto-detect wall corners, T-junctions, and span intervals to place RCC columns");
        subLbl.setFont(new Font("Segoe UI", Font.PLAIN, 11));
        subLbl.setForeground(new Color(148, 163, 184));
        g.gridy = 1;
        form.add(subLbl, g);
        g.gridwidth = 1;

        // 1. Column Size Preset
        g.gridy = 2; g.gridx = 0;
        JLabel lColSize = new JLabel("Column Size:"); lColSize.setForeground(new Color(203, 213, 225));
        form.add(lColSize, g);
        g.gridx = 1;
        JComboBox<String> colSizeCombo = new JComboBox<>(new String[]{
                "9\" × 12\" (Standard Residential G+1)",
                "9\" × 15\" (Heavy Beam Span / G+2)",
                "9\" × 9\" (Square Internal Post)",
                "12\" × 18\" (Commercial / Multi-Story)"
        });
        styleComboBox(colSizeCombo);
        form.add(colSizeCombo, g);

        // 2. Maximum Unbraced Span Interval
        g.gridy = 3; g.gridx = 0;
        JLabel lMaxSpan = new JLabel("Max Span Distance (ft):"); lMaxSpan.setForeground(new Color(203, 213, 225));
        form.add(lMaxSpan, g);
        g.gridx = 1;
        JTextField maxSpanFld = new JTextField("14.0", 8);
        form.add(maxSpanFld, g);

        // 3. Placement Mode Options
        g.gridy = 4; g.gridx = 0;
        JLabel lMode = new JLabel("Placement Rule:"); lMode.setForeground(new Color(203, 213, 225));
        form.add(lMode, g);
        g.gridx = 1;
        JComboBox<String> ruleCombo = new JComboBox<>(new String[]{
                "All Wall Corners + Midpoints on Spans > Max",
                "Exterior Perimeter Corners Only",
                "Full Rectangular Structural Grid Matrix"
        });
        styleComboBox(ruleCombo);
        form.add(ruleCombo, g);

        // 4. Clear existing columns checkbox
        g.gridy = 5; g.gridx = 0; g.gridwidth = 2;
        JCheckBox clearOldBox = new JCheckBox("Replace existing columns (Clean layout)", true);
        clearOldBox.setOpaque(false);
        clearOldBox.setForeground(new Color(56, 189, 248));
        form.add(clearOldBox, g);
        g.gridwidth = 1;

        dlg.add(form, BorderLayout.CENTER);

        // Buttons
        JPanel btnPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT, 10, 12));
        btnPanel.setOpaque(false);
        btnPanel.setBorder(BorderFactory.createMatteBorder(1, 0, 0, 0, new Color(30, 41, 59)));

        ModernButton cancelBtn = new ModernButton("Cancel", new Color(24, 33, 53), new Color(148, 163, 184), new Color(51, 65, 85));
        cancelBtn.addActionListener(e -> dlg.dispose());

        ModernButton runBtn = new ModernButton("Auto-Place Columns", new Color(2, 132, 199), Color.WHITE, new Color(56, 189, 248));
        runBtn.setPreferredSize(new Dimension(170, 32));
        runBtn.addActionListener(e -> {
            try {
                if (walls.isEmpty()) {
                    JOptionPane.showMessageDialog(dlg,
                            "No walls found on the canvas.\nPlease draw walls or build a room first using the Room Builder before placing structural columns.",
                            "No Walls Found", JOptionPane.WARNING_MESSAGE);
                    return;
                }

                double maxSpan = Double.parseDouble(maxSpanFld.getText().trim());
                if (maxSpan < 6.0) maxSpan = 6.0;

                double colW = 0.75 * FT_PX, colH = 1.0 * FT_PX; // 9"x12" default
                int cIdx = colSizeCombo.getSelectedIndex();
                if (cIdx == 0) { colW = 0.75 * FT_PX; colH = 1.0 * FT_PX; }
                else if (cIdx == 1) { colW = 0.75 * FT_PX; colH = 1.25 * FT_PX; }
                else if (cIdx == 2) { colW = 0.75 * FT_PX; colH = 0.75 * FT_PX; }
                else if (cIdx == 3) { colW = 1.0 * FT_PX; colH = 1.5 * FT_PX; }

                int rule = ruleCombo.getSelectedIndex();
                boolean clearOld = clearOldBox.isSelected();

                int placed = generateStructuralColumnGrid(colW, colH, maxSpan, rule, clearOld);
                dlg.dispose();
                JOptionPane.showMessageDialog(this,
                        "Successfully placed " + placed + " RCC Structural Columns on your floor plan.",
                        "Column Grid Complete", JOptionPane.INFORMATION_MESSAGE);
            } catch (Exception ex) {
                JOptionPane.showMessageDialog(dlg, "Error generating column grid: " + ex.getMessage(), "Error", JOptionPane.ERROR_MESSAGE);
            }
        });

        btnPanel.add(cancelBtn);
        btnPanel.add(runBtn);
        dlg.add(btnPanel, BorderLayout.SOUTH);

        dlg.pack();
        dlg.setLocationRelativeTo(this);
        dlg.setVisible(true);
    }

    /**
     * Algorithmic RCC Column Placement Engine:
     * Discovers wall corner vertices, T-junctions, and span subdivisions.
     * Prevents overlapping duplicate columns within a 2 ft threshold.
     */
    public int generateStructuralColumnGrid(double colW, double colH, double maxSpanFt, int rule, boolean clearOld) {
        if (walls.isEmpty()) return 0;
        saveUndoState();

        if (clearOld) {
            elements.removeIf(el -> el.type.startsWith("column"));
        }

        List<Point2D.Double> targetPoints = new ArrayList<>();
        double tol = 1.5 * FT_PX; // 1.5 ft cluster tolerance

        if (rule == 2) {
            // ─── RULE 2: Full Rectangular Structural Grid Matrix ───
            double minX = Double.MAX_VALUE, maxX = -Double.MAX_VALUE;
            double minY = Double.MAX_VALUE, maxY = -Double.MAX_VALUE;
            for (Wall w : walls) {
                minX = Math.min(minX, Math.min(w.x1, w.x2)); maxX = Math.max(maxX, Math.max(w.x1, w.x2));
                minY = Math.min(minY, Math.min(w.y1, w.y2)); maxY = Math.max(maxY, Math.max(w.y1, w.y2));
            }

            double bayPx = Math.max(6.0, maxSpanFt) * FT_PX;
            int xSteps = Math.max(1, (int) Math.round((maxX - minX) / bayPx));
            int ySteps = Math.max(1, (int) Math.round((maxY - minY) / bayPx));
            double dx = (maxX - minX) / xSteps;
            double dy = (maxY - minY) / ySteps;

            for (int i = 0; i <= xSteps; i++) {
                double gx = minX + i * dx;
                for (int j = 0; j <= ySteps; j++) {
                    double gy = minY + j * dy;
                    // Keep candidate if it is near an existing wall
                    boolean nearWall = false;
                    for (Wall w : walls) {
                        if (Line2D.ptSegDist(w.x1, w.y1, w.x2, w.y2, gx, gy) <= tol * 2.0) {
                            nearWall = true;
                            break;
                        }
                    }
                    if (nearWall) {
                        addUniquePoint(targetPoints, gx, gy, tol);
                    }
                }
            }
        } else {
            // ─── RULE 0 & 1: Wall Corners, T-Junctions & Mid-Spans ───
            // 1. Collect all wall endpoints (Corners & free ends)
            for (Wall w : walls) {
                addUniquePoint(targetPoints, w.x1, w.y1, tol);
                addUniquePoint(targetPoints, w.x2, w.y2, tol);
            }

            // 1b. Collect T-junctions and Cross-intersections where walls meet or cross
            for (int i = 0; i < walls.size(); i++) {
                Wall w1 = walls.get(i);
                for (int j = i + 1; j < walls.size(); j++) {
                    Wall w2 = walls.get(j);
                    // Check if w1 endpoint lands along w2 interior
                    checkAndAddTeeJunction(targetPoints, w1.x1, w1.y1, w2, tol);
                    checkAndAddTeeJunction(targetPoints, w1.x2, w1.y2, w2, tol);
                    checkAndAddTeeJunction(targetPoints, w2.x1, w2.y1, w1, tol);
                    checkAndAddTeeJunction(targetPoints, w2.x2, w2.y2, w1, tol);

                    // Check if segments cross
                    if (Line2D.linesIntersect(w1.x1, w1.y1, w1.x2, w1.y2, w2.x1, w2.y1, w2.x2, w2.y2)) {
                        Point2D.Double crossPt = computeLineIntersection(w1, w2);
                        if (crossPt != null) addUniquePoint(targetPoints, crossPt.x, crossPt.y, tol);
                    }
                }
            }

            // 2. Subdivide long unbraced wall spans exceeding maxSpanFt
            if (rule == 0) { // All corners + midpoints
                double maxSpanPx = maxSpanFt * FT_PX;
                for (Wall w : walls) {
                    double len = w.getLength();
                    if (len > maxSpanPx) {
                        int divisions = (int) Math.ceil(len / maxSpanPx);
                        double segDx = (w.x2 - w.x1) / divisions;
                        double segDy = (w.y2 - w.y1) / divisions;
                        for (int k = 1; k < divisions; k++) {
                            addUniquePoint(targetPoints, w.x1 + segDx * k, w.y1 + segDy * k, tol);
                        }
                    }
                }
            } else if (rule == 1) {
                // Exterior Perimeter Corners Only
                double minX = Double.MAX_VALUE, maxX = -Double.MAX_VALUE;
                double minY = Double.MAX_VALUE, maxY = -Double.MAX_VALUE;
                for (Wall w : walls) {
                    minX = Math.min(minX, Math.min(w.x1, w.x2)); maxX = Math.max(maxX, Math.max(w.x1, w.x2));
                    minY = Math.min(minY, Math.min(w.y1, w.y2)); maxY = Math.max(maxY, Math.max(w.y1, w.y2));
                }
                List<Point2D.Double> extOnly = new ArrayList<>();
                for (Point2D.Double pt : targetPoints) {
                    if (Math.abs(pt.x - minX) < tol || Math.abs(pt.x - maxX) < tol ||
                        Math.abs(pt.y - minY) < tol || Math.abs(pt.y - maxY) < tol) {
                        extOnly.add(pt);
                    }
                }
                targetPoints = extOnly;
            }
        }

        // 3. Place CADElement columns centered on candidate coordinates & auto-select them
        clearSelection();
        int count = 0;
        for (Point2D.Double pt : targetPoints) {
            // Check if column already exists at this spot
            boolean exists = false;
            for (CADElement el : elements) {
                if (el.type.startsWith("column")) {
                    if (Point2D.distance(pt.x, pt.y, el.x + el.w / 2.0, el.y + el.h / 2.0) < tol) {
                        exists = true; break;
                    }
                }
            }
            if (!exists) {
                CADElement col = new CADElement("column", "RCC Column", pt.x - colW / 2.0, pt.y - colH / 2.0, colW, colH);
                elements.add(col);
                addToSelection(col);
                count++;
            }
        }

        // Switch to SELECT mode so user can immediately move/inspect/resize placed columns
        currentTool = ToolMode.SELECT;
        selectToolButton(ToolMode.SELECT);

        markProjectDirty(true);
        updateProperties();
        viewportPanel.zoomToFit();
        return count;
    }

    private void checkAndAddTeeJunction(List<Point2D.Double> list, double px, double py, Wall w, double tol) {
        double d = Line2D.ptSegDist(w.x1, w.y1, w.x2, w.y2, px, py);
        if (d < tol) {
            // Project onto segment
            double dx = w.x2 - w.x1, dy = w.y2 - w.y1;
            double lenSq = dx * dx + dy * dy;
            if (lenSq > 0.001) {
                double t = Math.max(0, Math.min(1, ((px - w.x1) * dx + (py - w.y1) * dy) / lenSq));
                addUniquePoint(list, w.x1 + t * dx, w.y1 + t * dy, tol);
            }
        }
    }

    private Point2D.Double computeLineIntersection(Wall w1, Wall w2) {
        double x1 = w1.x1, y1 = w1.y1, x2 = w1.x2, y2 = w1.y2;
        double x3 = w2.x1, y3 = w2.y1, x4 = w2.x2, y4 = w2.y2;
        double denom = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4);
        if (Math.abs(denom) < 1e-6) return null;
        double px = ((x1 * y2 - y1 * x2) * (x3 - x4) - (x1 - x2) * (x3 * y4 - y3 * x4)) / denom;
        double py = ((x1 * y2 - y1 * x2) * (y3 - y4) - (y1 - y2) * (x3 * y4 - y3 * x4)) / denom;
        return new Point2D.Double(px, py);
    }

    private void addUniquePoint(List<Point2D.Double> list, double x, double y, double tol) {
        for (Point2D.Double p : list) {
            if (Point2D.distance(p.x, p.y, x, y) < tol) return;
        }
        list.add(new Point2D.Double(x, y));
    }

    public void setElevationView(String viewName) {
        if (!splitElevationBtn.isSelected()) {
            splitElevationBtn.setSelected(true);
            setSplitElevationView(true);
        }
        if (elevationViewportPanel != null) {
            elevationViewportPanel.setCurrentView(viewName);
        }
        if (viewportPanel != null) {
            viewportPanel.showToastNotification("Live Elevation: " + viewName);
            viewportPanel.repaint();
        }
    }

    public void setSplitElevationView(boolean enable) {
        if (splitElevationBtn != null && splitElevationBtn.isSelected() != enable) {
            splitElevationBtn.setSelected(enable);
        }
        if (elevationViewportPanel != null) {
            elevationViewportPanel.setVisible(enable);
            if (mainCenterSplit != null) {
                mainCenterSplit.setDividerSize(enable ? 6 : 0);
                if (enable) {
                    mainCenterSplit.setDividerLocation(0.55);
                    elevationViewportPanel.zoomToFit();
                    elevationViewportPanel.repaint();
                }
                mainCenterSplit.revalidate();
            }
        }
        if (viewportPanel != null) {
            viewportPanel.showToastNotification(enable ? "Split View: 2D Floor Plan + Live Elevation Active" : "Floor Plan Full Canvas");
            viewportPanel.repaint();
        }
    }

    private void styleSpinner(JSpinner spinner) {
        spinner.setPreferredSize(new Dimension(100, 26));
        JComponent editor = spinner.getEditor();
        if (editor instanceof JSpinner.DefaultEditor) {
            JTextField tf = ((JSpinner.DefaultEditor) editor).getTextField();
            tf.setBackground(new Color(24, 33, 53));
            tf.setForeground(Color.WHITE);
            tf.setCaretColor(new Color(56, 189, 248));
            tf.setFont(new Font("Segoe UI", Font.BOLD, 12));
            tf.setBorder(BorderFactory.createEmptyBorder(2, 4, 2, 4));
        }
        spinner.setBorder(BorderFactory.createLineBorder(new Color(51, 65, 85)));
    }

    public void showStaircaseDialog(CADElement existingStair) {
        boolean isEditing = (existingStair != null);
        JDialog dlg = new JDialog(this, isEditing ? "Modify Architectural Staircase" : "Architectural Staircase Library & Parametric Generator", true);
        dlg.setLayout(new BorderLayout());
        dlg.getContentPane().setBackground(new Color(15, 23, 42));

        String[] types = {
            "stair-straight",
            "stair-dogleg",
            "stair-lshape",
            "stair-openwell",
            "stair-spiral",
            "stair-bifurcated"
        };
        String[] typeNames = {
            "Straight Flight Staircase (3'-6\" × 12'-0\")",
            "Dog-Legged / Half-Turn with Mid-Landing (7'-0\" × 10'-0\")",
            "L-Shaped Quarter-Turn (7'-0\" × 10'-0\")",
            "Open-Well with Lightwell (8'-0\" × 12'-0\")",
            "Spiral / Circular Staircase (6'-0\" × 6'-0\")",
            "Bifurcated Grand Entrance Staircase (10'-0\" × 14'-0\")"
        };

        JComboBox<String> typeCombo = new JComboBox<>(typeNames);
        styleComboBox(typeCombo);

        double initW = isEditing ? (existingStair.w / FT_PX) : 7.0;
        double initD = isEditing ? (existingStair.h / FT_PX) : 10.0;
        if (isEditing && existingStair.type != null) {
            for (int i = 0; i < types.length; i++) {
                if (types[i].equals(existingStair.type)) {
                    typeCombo.setSelectedIndex(i);
                    break;
                }
            }
        } else {
            typeCombo.setSelectedIndex(1); // Dogleg default
        }

        JSpinner widthSpinner = new JSpinner(new SpinnerNumberModel(initW, 2.5, 25.0, 0.5));
        JSpinner depthSpinner = new JSpinner(new SpinnerNumberModel(initD, 2.5, 30.0, 0.5));
        JSpinner heightSpinner = new JSpinner(new SpinnerNumberModel(10.0, 7.0, 16.0, 0.5));
        styleSpinner(widthSpinner);
        styleSpinner(depthSpinner);
        styleSpinner(heightSpinner);

        JLabel codeCalcLbl = new JLabel();
        codeCalcLbl.setFont(new Font("Segoe UI", Font.PLAIN, 11));
        codeCalcLbl.setForeground(new Color(52, 211, 153));

        Runnable updateCalc = () -> {
            double htFt = ((Number) heightSpinner.getValue()).doubleValue();
            double dFt = ((Number) depthSpinner.getValue()).doubleValue();
            int risers = (int) Math.round((htFt * 12.0) / 7.0);
            if (risers < 12) risers = 12;
            double riserInches = (htFt * 12.0) / risers;
            double treadInches = (dFt * 12.0) / Math.max(8, risers / 2);
            codeCalcLbl.setText(String.format("<html><b>Riser:</b> %.2f\" (%d steps) &nbsp;|&nbsp; <b>Going/Tread:</b> %.1f\"<br><span style='color:#38bdf8'>✓ Meets IRC/NBC Building Code (&le;7.75\" Riser)</span></html>",
                    riserInches, risers, treadInches));
        };
        updateCalc.run();
        heightSpinner.addChangeListener(e -> updateCalc.run());
        depthSpinner.addChangeListener(e -> updateCalc.run());

        JPanel leftPanel = new JPanel(new GridBagLayout());
        leftPanel.setOpaque(false);
        leftPanel.setBorder(new EmptyBorder(16, 20, 16, 20));
        GridBagConstraints g = new GridBagConstraints();
        g.insets = new Insets(6, 6, 6, 6);
        g.fill = GridBagConstraints.HORIZONTAL;

        g.gridx = 0; g.gridy = 0;
        JLabel tLbl = new JLabel("STAIRCASE TYPE:");
        tLbl.setFont(new Font("Consolas", Font.BOLD, 11));
        tLbl.setForeground(new Color(148, 163, 184));
        leftPanel.add(tLbl, g);

        g.gridx = 1;
        leftPanel.add(typeCombo, g);

        g.gridx = 0; g.gridy = 1;
        JLabel wLbl = new JLabel("TOTAL WIDTH (FT):");
        wLbl.setFont(new Font("Consolas", Font.BOLD, 11));
        wLbl.setForeground(new Color(148, 163, 184));
        leftPanel.add(wLbl, g);

        g.gridx = 1;
        leftPanel.add(widthSpinner, g);

        g.gridx = 0; g.gridy = 2;
        JLabel dLbl = new JLabel("LENGTH / DEPTH (FT):");
        dLbl.setFont(new Font("Consolas", Font.BOLD, 11));
        dLbl.setForeground(new Color(148, 163, 184));
        leftPanel.add(dLbl, g);

        g.gridx = 1;
        leftPanel.add(depthSpinner, g);

        g.gridx = 0; g.gridy = 3;
        JLabel hLbl = new JLabel("FLOOR HEIGHT (FT):");
        hLbl.setFont(new Font("Consolas", Font.BOLD, 11));
        hLbl.setForeground(new Color(148, 163, 184));
        leftPanel.add(hLbl, g);

        g.gridx = 1;
        leftPanel.add(heightSpinner, g);

        g.gridx = 0; g.gridy = 4; g.gridwidth = 2;
        leftPanel.add(codeCalcLbl, g);

        JPanel previewPanel = new JPanel() {
            @Override
            protected void paintComponent(Graphics gr) {
                super.paintComponent(gr);
                Graphics2D g2 = (Graphics2D) gr.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

                int pw = getWidth(), ph = getHeight();
                g2.setColor(new Color(11, 19, 36));
                g2.fillRect(0, 0, pw, ph);

                double wFt = ((Number) widthSpinner.getValue()).doubleValue();
                double dFt = ((Number) depthSpinner.getValue()).doubleValue();
                int selIdx = typeCombo.getSelectedIndex();
                String selType = types[Math.max(0, Math.min(types.length - 1, selIdx))];

                double margin = 30.0;
                double scale = Math.min((pw - margin * 2) / (wFt * FT_PX), (ph - margin * 2) / (dFt * FT_PX));
                int drawW = (int)(wFt * FT_PX * scale);
                int drawH = (int)(dFt * FT_PX * scale);
                int ox = (pw - drawW) / 2;
                int oy = (ph - drawH) / 2;

                AffineTransform old = g2.getTransform();
                g2.translate(ox, oy);
                renderArchitecturalStaircase(g2, selType, drawW, drawH, false, scale, true);
                g2.setTransform(old);

                g2.setColor(new Color(56, 189, 248));
                g2.setFont(new Font("Consolas", Font.BOLD, 10));
                FontMetrics fm = g2.getFontMetrics();
                String wStr = String.format("%.1f'", wFt);
                g2.drawString(wStr, ox + (drawW - fm.stringWidth(wStr)) / 2, oy - 8);
                String dStr = String.format("%.1f'", dFt);
                g2.drawString(dStr, ox + drawW + 6, oy + drawH / 2);

                g2.dispose();
            }
        };
        previewPanel.setPreferredSize(new Dimension(280, 280));
        previewPanel.setBorder(BorderFactory.createLineBorder(new Color(51, 65, 85)));

        typeCombo.addActionListener(e -> {
            int idx = typeCombo.getSelectedIndex();
            if (idx == 0) { widthSpinner.setValue(3.5); depthSpinner.setValue(12.0); }
            else if (idx == 1) { widthSpinner.setValue(7.0); depthSpinner.setValue(10.0); }
            else if (idx == 2) { widthSpinner.setValue(7.0); depthSpinner.setValue(10.0); }
            else if (idx == 3) { widthSpinner.setValue(8.0); depthSpinner.setValue(12.0); }
            else if (idx == 4) { widthSpinner.setValue(6.0); depthSpinner.setValue(6.0); }
            else if (idx == 5) { widthSpinner.setValue(10.0); depthSpinner.setValue(14.0); }
            updateCalc.run();
            previewPanel.repaint();
        });
        widthSpinner.addChangeListener(e -> previewPanel.repaint());
        depthSpinner.addChangeListener(e -> previewPanel.repaint());

        JPanel center = new JPanel(new BorderLayout());
        center.setOpaque(false);
        center.add(leftPanel, BorderLayout.CENTER);
        center.add(previewPanel, BorderLayout.EAST);
        dlg.add(center, BorderLayout.CENTER);

        JPanel botBar = new JPanel(new FlowLayout(FlowLayout.RIGHT, 10, 10));
        botBar.setBackground(new Color(24, 33, 53));
        botBar.setBorder(BorderFactory.createMatteBorder(1, 0, 0, 0, new Color(51, 65, 85)));

        ModernButton cancelBtn = new ModernButton("Cancel", new Color(30, 41, 59), Color.WHITE, new Color(51, 65, 85));
        cancelBtn.addActionListener(e -> dlg.dispose());

        ModernButton insertBtn = new ModernButton(isEditing ? "Apply Changes" : "Insert Staircase",
                new Color(168, 85, 247), Color.WHITE, new Color(147, 51, 234));
        insertBtn.setFont(new Font("Segoe UI", Font.BOLD, 12));
        insertBtn.addActionListener(e -> {
            saveUndoState();
            double wFt = ((Number) widthSpinner.getValue()).doubleValue();
            double dFt = ((Number) depthSpinner.getValue()).doubleValue();
            int selIdx = typeCombo.getSelectedIndex();
            String selType = types[Math.max(0, Math.min(types.length - 1, selIdx))];
            String selName = typeNames[Math.max(0, Math.min(types.length - 1, selIdx))];

            if (isEditing) {
                existingStair.type = selType;
                existingStair.name = selName;
                existingStair.w = wFt * FT_PX;
                existingStair.h = dFt * FT_PX;
            } else {
                int viewW = viewportPanel.getWidth();
                int viewH = viewportPanel.getHeight();
                Point2D.Double centerWorld = viewportPanel.screenToWorld(viewW / 2, viewH / 2);
                CADElement newStair = new CADElement(selType, selName,
                        centerWorld.x - (wFt * FT_PX) / 2.0,
                        centerWorld.y - (dFt * FT_PX) / 2.0,
                        wFt * FT_PX, dFt * FT_PX);
                elements.add(newStair);
                clearSelection();
                addToSelection(newStair);
            }
            markProjectDirty(true);
            viewportPanel.repaint();
            dlg.dispose();
            viewportPanel.showToastNotification((isEditing ? "Updated " : "Inserted ") + selName);
        });

        botBar.add(cancelBtn);
        botBar.add(insertBtn);
        dlg.add(botBar, BorderLayout.SOUTH);

        dlg.pack();
        dlg.setLocationRelativeTo(this);
        dlg.setVisible(true);
    }

    private void renderArchitecturalStaircase(Graphics2D g2, String type, int sw, int sh,
                                              boolean isMonochrome, double scale, boolean isDark) {
        Color bg = isDark ? new Color(15, 23, 42) : Color.WHITE;
        Color borderCol = isMonochrome ? Color.BLACK : (isDark ? new Color(56, 189, 248) : new Color(15, 23, 42));
        Color treadCol = isMonochrome ? Color.DARK_GRAY : (isDark ? new Color(148, 163, 184) : new Color(71, 85, 105));
        Color arrowCol = isMonochrome ? Color.BLACK : (isDark ? new Color(245, 158, 11) : new Color(2, 132, 199));
        Color handrailCol = isMonochrome ? Color.BLACK : (isDark ? new Color(52, 211, 153) : new Color(14, 116, 144));
        Color landingCol = isMonochrome ? new Color(245, 245, 245) : (isDark ? new Color(30, 41, 59) : new Color(241, 245, 249));

        g2.setColor(bg);
        g2.fillRect(0, 0, sw, sh);
        g2.setColor(borderCol);
        g2.setStroke(new BasicStroke((float) Math.max(1.5, 2.0 / scale)));
        g2.drawRect(0, 0, sw, sh);

        float sThin = (float) Math.max(0.8, 1.0 / scale);
        float sMed = (float) Math.max(1.2, 1.5 / scale);
        float sHeavy = (float) Math.max(1.8, 2.2 / scale);

        if ("stair-spiral".equals(type)) {
            int r = Math.min(sw, sh) / 2;
            int cx = sw / 2, cy = sh / 2;
            int centerR = Math.max(6, (int)(r * 0.2));

            g2.setColor(borderCol);
            g2.setStroke(new BasicStroke(sHeavy));
            g2.drawOval(cx - r + 2, cy - r + 2, (r - 2) * 2, (r - 2) * 2);

            g2.setColor(landingCol);
            g2.fillOval(cx - centerR, cy - centerR, centerR * 2, centerR * 2);
            g2.setColor(borderCol);
            g2.setStroke(new BasicStroke(sMed));
            g2.drawOval(cx - centerR, cy - centerR, centerR * 2, centerR * 2);

            int numSpokes = 16;
            g2.setColor(treadCol);
            g2.setStroke(new BasicStroke(sThin));
            for (int i = 0; i < numSpokes; i++) {
                double angle = (2.0 * Math.PI / numSpokes) * i;
                int x1 = cx + (int)(Math.cos(angle) * centerR);
                int y1 = cy + (int)(Math.sin(angle) * centerR);
                int x2 = cx + (int)(Math.cos(angle) * (r - 2));
                int y2 = cy + (int)(Math.sin(angle) * (r - 2));
                g2.drawLine(x1, y1, x2, y2);
            }

            int walkR = (centerR + r) / 2;
            g2.setColor(arrowCol);
            g2.setStroke(new BasicStroke(sMed));
            g2.drawArc(cx - walkR, cy - walkR, walkR * 2, walkR * 2, 20, 270);
            int sx = cx + (int)(Math.cos(Math.toRadians(20)) * walkR);
            int sy = cy - (int)(Math.sin(Math.toRadians(20)) * walkR);
            g2.fillOval(sx - 3, sy - 3, 6, 6);
            int ex = cx + (int)(Math.cos(Math.toRadians(290)) * walkR);
            int ey = cy - (int)(Math.sin(Math.toRadians(290)) * walkR);
            g2.fillPolygon(new int[]{ex - 4, ex + 4, ex}, new int[]{ey - 6, ey - 6, ey + 2}, 3);

            g2.setFont(new Font("Consolas", Font.BOLD, 8));
            g2.drawString("UP \u21bb", cx - 14, cy + centerR + 14);

        } else if ("stair-dogleg".equals(type)) {
            int landingH = Math.max(16, (int)(sh * 0.30));
            int midX = sw / 2;

            g2.setColor(landingCol);
            g2.fillRect(0, 0, sw, landingH);
            g2.setColor(borderCol);
            g2.setStroke(new BasicStroke(sMed));
            g2.drawLine(0, landingH, sw, landingH);

            g2.setStroke(new BasicStroke(sHeavy));
            g2.drawLine(midX, landingH, midX, sh);

            int numTreads = 8;
            int flightH = sh - landingH;
            g2.setColor(treadCol);
            g2.setStroke(new BasicStroke(sThin));
            for (int i = 1; i <= numTreads; i++) {
                int ty = landingH + (flightH * i) / numTreads;
                g2.drawLine(0, ty, midX, ty);
                g2.drawLine(midX, ty, sw, ty);
            }

            int wLeft = midX / 2;
            int wRight = midX + midX / 2;
            int wLandY = landingH / 2;
            g2.setColor(arrowCol);
            g2.setStroke(new BasicStroke(sMed));
            g2.drawLine(wLeft, sh - 10, wLeft, wLandY);
            g2.drawArc(wLeft, wLandY - (wRight - wLeft) / 2, wRight - wLeft, wRight - wLeft, 0, 180);
            g2.drawLine(wRight, wLandY, wRight, sh - 10);

            g2.fillOval(wLeft - 3, sh - 12, 6, 6);
            g2.fillPolygon(new int[]{wRight - 4, wRight + 4, wRight}, new int[]{sh - 14, sh - 14, sh - 6}, 3);

            g2.setFont(new Font("Consolas", Font.BOLD, 8));
            g2.drawString("UP \u2191", wLeft - 12, sh - 16);
            g2.drawString("LANDING", midX - 22, landingH / 2 + 4);

        } else if ("stair-lshape".equals(type)) {
            int landW = Math.max(18, (int)(sw * 0.45));
            int landH = Math.max(18, (int)(sh * 0.40));

            g2.setColor(landingCol);
            g2.fillRect(sw - landW, 0, landW, landH);
            g2.setColor(borderCol);
            g2.setStroke(new BasicStroke(sMed));
            g2.drawRect(sw - landW, 0, landW, landH);

            int treads1 = 7;
            g2.setColor(treadCol);
            g2.setStroke(new BasicStroke(sThin));
            for (int i = 1; i <= treads1; i++) {
                int ty = landH + ((sh - landH) * i) / treads1;
                g2.drawLine(0, ty, sw - landW, ty);
            }

            int treads2 = 5;
            for (int i = 1; i < treads2; i++) {
                int tx = ((sw - landW) * i) / treads2;
                g2.drawLine(tx, 0, tx, landH);
            }

            g2.setColor(borderCol);
            g2.setStroke(new BasicStroke(sHeavy));
            g2.drawLine(sw - landW, landH, sw - landW, sh);
            g2.drawLine(0, landH, sw - landW, landH);

            int wX1 = (sw - landW) / 2;
            int wY2 = landH / 2;
            g2.setColor(arrowCol);
            g2.setStroke(new BasicStroke(sMed));
            g2.drawLine(wX1, sh - 10, wX1, wY2);
            g2.drawLine(wX1, wY2, 10, wY2);
            g2.fillOval(wX1 - 3, sh - 12, 6, 6);
            g2.fillPolygon(new int[]{14, 14, 6}, new int[]{wY2 - 4, wY2 + 4, wY2}, 3);

            g2.setFont(new Font("Consolas", Font.BOLD, 8));
            g2.drawString("UP \u2191", wX1 - 10, sh - 16);
            g2.drawString("LANDING", sw - landW + 4, landH / 2 + 4);

        } else if ("stair-openwell".equals(type)) {
            int landingH = Math.max(16, (int)(sh * 0.28));
            int fW = (int)(sw * 0.38);
            int wellW = sw - fW * 2;

            g2.setColor(landingCol);
            g2.fillRect(0, 0, sw, landingH);
            g2.setColor(borderCol);
            g2.setStroke(new BasicStroke(sMed));
            g2.drawLine(0, landingH, sw, landingH);

            g2.setColor(bg);
            g2.fillRect(fW, landingH, wellW, sh - landingH);
            g2.setColor(handrailCol);
            g2.setStroke(new BasicStroke(sHeavy));
            g2.drawRect(fW, landingH, wellW, sh - landingH);

            int treads = 8;
            int flightH = sh - landingH;
            g2.setColor(treadCol);
            g2.setStroke(new BasicStroke(sThin));
            for (int i = 1; i <= treads; i++) {
                int ty = landingH + (flightH * i) / treads;
                g2.drawLine(0, ty, fW, ty);
                g2.drawLine(sw - fW, ty, sw, ty);
            }

            int wLeft = fW / 2;
            int wRight = sw - fW / 2;
            int wLandY = landingH / 2;
            g2.setColor(arrowCol);
            g2.setStroke(new BasicStroke(sMed));
            g2.drawLine(wLeft, sh - 10, wLeft, wLandY);
            g2.drawLine(wLeft, wLandY, wRight, wLandY);
            g2.drawLine(wRight, wLandY, wRight, sh - 10);
            g2.fillOval(wLeft - 3, sh - 12, 6, 6);
            g2.fillPolygon(new int[]{wRight - 4, wRight + 4, wRight}, new int[]{sh - 14, sh - 14, sh - 6}, 3);

            g2.setFont(new Font("Consolas", Font.BOLD, 8));
            g2.drawString("WELL", fW + 4, landingH + (sh - landingH) / 2);
            g2.drawString("UP \u2191", wLeft - 12, sh - 16);

        } else if ("stair-bifurcated".equals(type)) {
            int landingY = (int)(sh * 0.40);
            int landingH = (int)(sh * 0.22);
            int mainFlightW = (int)(sw * 0.55);
            int sideFlightW = (int)(sw * 0.30);

            g2.setColor(landingCol);
            g2.fillRect(0, landingY, sw, landingH);
            g2.setColor(borderCol);
            g2.setStroke(new BasicStroke(sMed));
            g2.drawRect(0, landingY, sw, landingH);

            int mainX1 = (sw - mainFlightW) / 2;
            int mainX2 = mainX1 + mainFlightW;
            g2.setColor(borderCol);
            g2.setStroke(new BasicStroke(sHeavy));
            g2.drawLine(mainX1, landingY + landingH, mainX1, sh);
            g2.drawLine(mainX2, landingY + landingH, mainX2, sh);

            int treadsMain = 6;
            g2.setColor(treadCol);
            g2.setStroke(new BasicStroke(sThin));
            for (int i = 1; i <= treadsMain; i++) {
                int ty = landingY + landingH + ((sh - (landingY + landingH)) * i) / treadsMain;
                g2.drawLine(mainX1, ty, mainX2, ty);
            }

            int treadsUp = 5;
            for (int i = 1; i <= treadsUp; i++) {
                int ty = (landingY * i) / treadsUp;
                g2.drawLine(0, ty, sideFlightW, ty);
                g2.drawLine(sw - sideFlightW, ty, sw, ty);
            }

            g2.setColor(borderCol);
            g2.setStroke(new BasicStroke(sHeavy));
            g2.drawLine(sideFlightW, 0, sideFlightW, landingY);
            g2.drawLine(sw - sideFlightW, 0, sw - sideFlightW, landingY);

            int midX = sw / 2;
            int landMidY = landingY + landingH / 2;
            g2.setColor(arrowCol);
            g2.setStroke(new BasicStroke(sMed));
            g2.drawLine(midX, sh - 10, midX, landMidY);
            g2.drawLine(midX, landMidY, sideFlightW / 2, landMidY);
            g2.drawLine(sideFlightW / 2, landMidY, sideFlightW / 2, 10);
            g2.drawLine(midX, landMidY, sw - sideFlightW / 2, landMidY);
            g2.drawLine(sw - sideFlightW / 2, landMidY, sw - sideFlightW / 2, 10);

            g2.fillOval(midX - 3, sh - 12, 6, 6);
            g2.fillPolygon(new int[]{sideFlightW / 2 - 4, sideFlightW / 2 + 4, sideFlightW / 2}, new int[]{14, 14, 6}, 3);
            g2.fillPolygon(new int[]{sw - sideFlightW / 2 - 4, sw - sideFlightW / 2 + 4, sw - sideFlightW / 2}, new int[]{14, 14, 6}, 3);

            g2.setFont(new Font("Consolas", Font.BOLD, 8));
            g2.drawString("GRAND STAIR", midX - 32, landingY + landingH / 2 + 4);

        } else {
            int treads = 12;
            int cutStep = 7;
            g2.setColor(treadCol);

            for (int t = 1; t < treads; t++) {
                int ty = (sh * t) / treads;
                if (t <= cutStep) {
                    g2.setStroke(new BasicStroke(sThin));
                    g2.drawLine(0, ty, sw, ty);
                } else {
                    g2.setStroke(new BasicStroke(sThin, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 10, new float[]{4, 3}, 0));
                    g2.drawLine(0, ty, sw, ty);
                }
            }

            int cutY = (sh * cutStep) / treads + (sh / (treads * 2));
            g2.setColor(isDark ? new Color(248, 113, 113) : new Color(220, 38, 38));
            g2.setStroke(new BasicStroke(sMed));
            int midX = sw / 2;
            g2.drawLine(0, cutY, midX - 10, cutY);
            g2.drawLine(midX - 10, cutY, midX - 4, cutY - 7);
            g2.drawLine(midX - 4, cutY - 7, midX + 4, cutY + 7);
            g2.drawLine(midX + 4, cutY + 7, midX + 10, cutY);
            g2.drawLine(midX + 10, cutY, sw, cutY);

            g2.setColor(arrowCol);
            g2.setStroke(new BasicStroke(sMed));
            g2.drawLine(sw / 2, sh - 10, sw / 2, 12);
            g2.fillOval(sw / 2 - 3, sh - 12, 6, 6);
            g2.fillPolygon(new int[]{sw / 2 - 4, sw / 2 + 4, sw / 2}, new int[]{16, 16, 8}, 3);

            g2.setFont(new Font("Consolas", Font.BOLD, 8));
            g2.drawString("UP \u2191", sw / 2 - 12, sh - 18);
        }
    }

    // ─── AutoCAD-Style Live Architectural Elevation Viewport ───
    public class CADElevationViewportPanel extends JPanel {
        private String currentView = "Front Facade (South)";
        private double ceilingHeightFt = 10.0;
        private boolean showDatums = true;
        private boolean showDimensions = true;
        private JComboBox<String> viewCombo;
        private JComboBox<String> heightCombo;
        private JCheckBox datumBox, dimBox;
        private JPanel canvasPanel;

        // Viewport camera (Pan & Zoom)
        private double panX = 0.0;
        private double panY = 0.0;
        private double zoom = 1.0;
        private Point lastMouse = null;
        private Point mousePos = new Point(-1, -1);

        public String getCurrentView() {
            return currentView;
        }

        public void setCurrentView(String view) {
            this.currentView = view;
            if (viewCombo != null && !view.equals(viewCombo.getSelectedItem())) {
                viewCombo.setSelectedItem(view);
            }
            zoomToFit();
            repaint();
            if (viewportPanel != null) viewportPanel.repaint();
        }

        public CADElevationViewportPanel() {
            setLayout(new BorderLayout());
            setBackground(new Color(15, 23, 42)); // Slate #0f172a
            setBorder(BorderFactory.createMatteBorder(0, 1, 0, 0, new Color(51, 65, 85)));

            // Top Header Control Bar
            JPanel topBar = new JPanel(new BorderLayout());
            topBar.setBackground(new Color(24, 33, 53));
            topBar.setBorder(BorderFactory.createMatteBorder(0, 0, 1, 0, new Color(51, 65, 85)));
            topBar.setPreferredSize(new Dimension(500, 34));

            JPanel leftGroup = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 3));
            leftGroup.setOpaque(false);

            JLabel titleBadge = new JLabel("LIVE ELEVATION");
            titleBadge.setFont(new Font("Consolas", Font.BOLD, 10));
            titleBadge.setForeground(new Color(52, 211, 153));
            titleBadge.setBorder(BorderFactory.createCompoundBorder(
                    BorderFactory.createLineBorder(new Color(52, 211, 153, 160), 1, true),
                    new EmptyBorder(1, 4, 1, 4)));
            leftGroup.add(titleBadge);

            viewCombo = new JComboBox<>(new String[]{
                    "Front Facade (South)",
                    "Rear Facade (North)",
                    "Left Elevation (West)",
                    "Right Elevation (East)",
                    "Section Cut A-A"
            });
            styleComboBox(viewCombo);
            viewCombo.setPreferredSize(new Dimension(150, 24));
            viewCombo.addActionListener(e -> {
                currentView = (String) viewCombo.getSelectedItem();
                zoomToFit();
                repaint();
                if (viewportPanel != null) viewportPanel.repaint();
            });
            leftGroup.add(viewCombo);

            heightCombo = new JComboBox<>(new String[]{"10'-0\" Ceil", "9'-0\" Ceil", "11'-0\" Ceil"});
            styleComboBox(heightCombo);
            heightCombo.setPreferredSize(new Dimension(90, 24));
            heightCombo.addActionListener(e -> {
                int idx = heightCombo.getSelectedIndex();
                ceilingHeightFt = (idx == 0 ? 10.0 : (idx == 1 ? 9.0 : 11.0));
                repaint();
            });
            leftGroup.add(heightCombo);

            datumBox = new JCheckBox("Datums", true);
            datumBox.setOpaque(false);
            datumBox.setForeground(new Color(203, 213, 225));
            datumBox.setFont(new Font("Segoe UI", Font.PLAIN, 10));
            datumBox.addActionListener(e -> { showDatums = datumBox.isSelected(); repaint(); });
            leftGroup.add(datumBox);

            dimBox = new JCheckBox("Dims", true);
            dimBox.setOpaque(false);
            dimBox.setForeground(new Color(203, 213, 225));
            dimBox.setFont(new Font("Segoe UI", Font.PLAIN, 10));
            dimBox.addActionListener(e -> { showDimensions = dimBox.isSelected(); repaint(); });
            leftGroup.add(dimBox);

            topBar.add(leftGroup, BorderLayout.CENTER);

            JPanel rightGroup = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 3));
            rightGroup.setOpaque(false);

            ModernButton fitBtn = new ModernButton("Fit", new Color(30, 41, 59), new Color(148, 163, 184), new Color(51, 65, 85));
            fitBtn.setFont(new Font("Segoe UI", Font.BOLD, 10));
            fitBtn.setPreferredSize(new Dimension(42, 24));
            fitBtn.addActionListener(e -> zoomToFit());
            rightGroup.add(fitBtn);

            ModernButton exportBtn = new ModernButton("Export", new Color(14, 116, 144), Color.WHITE, new Color(56, 189, 248));
            exportBtn.setFont(new Font("Segoe UI", Font.BOLD, 10));
            exportBtn.setPreferredSize(new Dimension(65, 24));
            exportBtn.addActionListener(e -> exportElevationImage());
            rightGroup.add(exportBtn);

            ModernButton closeBtn = new ModernButton("X", new Color(127, 29, 29), new Color(254, 205, 211), new Color(244, 63, 94));
            closeBtn.setFont(new Font("Segoe UI", Font.BOLD, 10));
            closeBtn.setPreferredSize(new Dimension(28, 24));
            closeBtn.setToolTipText("Close Live Elevation (F5)");
            closeBtn.addActionListener(e -> setSplitElevationView(false));
            rightGroup.add(closeBtn);

            topBar.add(rightGroup, BorderLayout.EAST);
            add(topBar, BorderLayout.NORTH);

            // Canvas
            canvasPanel = new JPanel() {
                @Override
                protected void paintComponent(Graphics g) {
                    super.paintComponent(g);
                    Graphics2D g2 = (Graphics2D) g.create();
                    g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                    g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
                    g2.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);

                    renderElevationView(g2, getWidth(), getHeight(), false);
                    drawAutoCADCrosshair(g2, getWidth(), getHeight());
                    g2.dispose();
                }
            };
            canvasPanel.setBackground(new Color(11, 15, 25));

            MouseAdapter ma = new MouseAdapter() {
                @Override
                public void mousePressed(MouseEvent e) {
                    lastMouse = e.getPoint();
                }
                @Override
                public void mouseDragged(MouseEvent e) {
                    if (lastMouse != null && (SwingUtilities.isMiddleMouseButton(e) || SwingUtilities.isRightMouseButton(e) || e.isShiftDown())) {
                        panX += (e.getX() - lastMouse.x);
                        panY += (e.getY() - lastMouse.y);
                        lastMouse = e.getPoint();
                        canvasPanel.repaint();
                    }
                }
                @Override
                public void mouseMoved(MouseEvent e) {
                    mousePos = e.getPoint();
                    canvasPanel.repaint();
                }
                @Override
                public void mouseWheelMoved(MouseWheelEvent e) {
                    double factor = (e.getPreciseWheelRotation() < 0) ? 1.15 : (1.0 / 1.15);
                    zoom = Math.max(0.2, Math.min(5.0, zoom * factor));
                    canvasPanel.repaint();
                }
            };
            canvasPanel.addMouseListener(ma);
            canvasPanel.addMouseMotionListener(ma);
            canvasPanel.addMouseWheelListener(ma);

            add(canvasPanel, BorderLayout.CENTER);
        }

        public void zoomToFit() {
            panX = 0;
            panY = 0;
            zoom = 1.0;
            if (canvasPanel != null) canvasPanel.repaint();
        }

        private void exportElevationImage() {
            JFileChooser fc = new JFileChooser();
            String name = currentView.replaceAll("[^a-zA-Z0-9_-]", "_") + ".png";
            fc.setSelectedFile(new File(name));
            if (fc.showSaveDialog(this) == JFileChooser.APPROVE_OPTION) {
                File f = fc.getSelectedFile();
                if (!f.getName().toLowerCase().endsWith(".png")) f = new File(f.getParentFile(), f.getName() + ".png");
                try {
                    BufferedImage img = new BufferedImage(1920, 1080, BufferedImage.TYPE_INT_ARGB);
                    Graphics2D g2 = img.createGraphics();
                    g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                    g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
                    renderElevationView(g2, 1920, 1080, true);
                    g2.dispose();
                    ImageIO.write(img, "png", f);
                    JOptionPane.showMessageDialog(this, "Elevation export saved:\n" + f.getAbsolutePath(), "Export Complete", JOptionPane.INFORMATION_MESSAGE);
                } catch (Exception ex) {
                    JOptionPane.showMessageDialog(this, "Failed to export elevation: " + ex.getMessage(), "Error", JOptionPane.ERROR_MESSAGE);
                }
            }
        }

        private void drawAutoCADCrosshair(Graphics2D g2, int w, int h) {
            if (mousePos == null || mousePos.x < 0 || mousePos.y < 0) return;
            int mx = mousePos.x, my = mousePos.y;

            // Thin crosshairs across viewport
            g2.setColor(new Color(56, 189, 248, 100)); // Cyan subtle
            g2.setStroke(new BasicStroke(1.0f));
            g2.drawLine(0, my, w, my);
            g2.drawLine(mx, 0, mx, h);

            // Center aperture pickbox (8x8)
            g2.setColor(new Color(56, 189, 248, 200));
            g2.drawRect(mx - 4, my - 4, 8, 8);

            // Coordinate HUD pill near cursor
            String coordText = String.format("X: %d | Y: %d", mx, my);
            g2.setFont(new Font("Consolas", Font.BOLD, 10));
            FontMetrics fm = g2.getFontMetrics();
            int tw = fm.stringWidth(coordText);
            int bx = Math.min(w - tw - 16, mx + 12);
            int by = Math.max(20, my - 8);

            g2.setColor(new Color(15, 23, 42, 220));
            g2.fillRoundRect(bx - 4, by - 12, tw + 8, 16, 4, 4);
            g2.setColor(new Color(56, 189, 248, 180));
            g2.drawRoundRect(bx - 4, by - 12, tw + 8, 16, 4, 4);
            g2.setColor(Color.WHITE);
            g2.drawString(coordText, bx, by);
        }

        private void renderElevationView(Graphics2D g2, int w, int h, boolean isExport) {
            Color bg = isExport ? Color.WHITE : (lightThemeEnabled ? new Color(248, 250, 252) : new Color(11, 15, 25));
            g2.setColor(bg);
            g2.fillRect(0, 0, w, h);

            if (walls.isEmpty()) {
                g2.setColor(new Color(100, 116, 139));
                g2.setFont(new Font("Segoe UI", Font.BOLD, 13));
                String msg = "Draw walls or place a room on the floor plan to see live elevation.";
                FontMetrics fm = g2.getFontMetrics();
                g2.drawString(msg, (w - fm.stringWidth(msg)) / 2, h / 2);
                return;
            }

            if (currentView.startsWith("Section")) {
                CADElement secTag = null;
                for (CADElement el : elements) {
                    if ("section".equals(el.type)) { secTag = el; break; }
                }
                if (secTag != null) {
                    renderSectionalElevationCut(g2, w, h, secTag, ceilingHeightFt, showDatums, true, isExport);
                    return;
                }
            }

            int viewMode = 0; // 0: South/Front, 1: North/Rear, 2: West/Left, 3: East/Right
            if (currentView.contains("North") || currentView.contains("Rear")) viewMode = 1;
            else if (currentView.contains("West") || currentView.contains("Left")) viewMode = 2;
            else if (currentView.contains("East") || currentView.contains("Right")) viewMode = 3;

            renderProjectedFacadeElevation(g2, w, h, viewMode, ceilingHeightFt, showDatums, showDimensions, isExport);
        }

        private void renderProjectedFacadeElevation(Graphics2D g2, int canvasW, int canvasH, int viewMode,
                                                    double ceilHtFt, boolean datums, boolean dims, boolean isExport) {
            // Find plan extent
            double minX = Double.MAX_VALUE, maxX = -Double.MAX_VALUE;
            double minY = Double.MAX_VALUE, maxY = -Double.MAX_VALUE;
            for (Wall w : walls) {
                minX = Math.min(minX, Math.min(w.x1, w.x2));
                maxX = Math.max(maxX, Math.max(w.x1, w.x2));
                minY = Math.min(minY, Math.min(w.y1, w.y2));
                maxY = Math.max(maxY, Math.max(w.y1, w.y2));
            }

            boolean isXAxis = (viewMode == 0 || viewMode == 1);
            double facadeLenPx = isXAxis ? (maxX - minX) : (maxY - minY);
            double facadeLenFt = Math.max(10.0, facadeLenPx / FT_PX);

            // Architectural heights
            double glFt = 0.0;
            double plinthFt = 1.5;
            double ceilFt = plinthFt + ceilHtFt;
            double slabFt = ceilFt + 0.5;
            double parapetFt = slabFt + 3.0;
            double fndFt = 2.5;
            double totalHtFt = parapetFt + fndFt + 1.0;

            int leftPad = 80;
            int rightPad = 80;
            int topPad = 60;
            int botPad = 60;

            int drawW = canvasW - leftPad - rightPad;
            int drawH = canvasH - topPad - botPad;
            if (drawW <= 40 || drawH <= 40) return;

            double baseScale = Math.min(drawW / facadeLenFt, drawH / totalHtFt);
            double scale = baseScale * zoom;

            int originX = leftPad + (int)((drawW - facadeLenFt * scale) / 2.0) + (int)panX;
            int glY = canvasH - botPad - (int)(fndFt * scale) + (int)panY;

            int plinthY = glY - (int)(plinthFt * scale);
            int ceilY = glY - (int)(ceilFt * scale);
            int slabY = glY - (int)(slabFt * scale);
            int parapetY = glY - (int)(parapetFt * scale);
            int fndY = glY + (int)(fndFt * scale);

            int bldgW = (int)(facadeLenFt * scale);

            // 1. Earth & Foundation
            g2.setColor(isExport ? new Color(241, 245, 249) : new Color(24, 33, 53));
            g2.fillRect(originX - 30, glY, bldgW + 60, fndY - glY);

            // Ground Line (GL)
            g2.setColor(new Color(34, 197, 94)); // Emerald Ground Line
            g2.setStroke(new BasicStroke(2.5f));
            g2.drawLine(originX - 50, glY, originX + bldgW + 50, glY);

            // 2. Plinth Beam
            g2.setColor(isExport ? new Color(226, 232, 240) : new Color(30, 41, 59));
            g2.fillRect(originX, plinthY, bldgW, glY - plinthY);
            g2.setColor(new Color(100, 116, 139));
            g2.setStroke(new BasicStroke(1.5f));
            g2.drawRect(originX, plinthY, bldgW, glY - plinthY);

            // 3. Main Facade Wall Mass
            g2.setColor(isExport ? new Color(248, 250, 252) : new Color(15, 23, 42));
            g2.fillRect(originX, ceilY, bldgW, plinthY - ceilY);

            // Subtle modern texture grooves
            g2.setColor(isExport ? new Color(226, 232, 240) : new Color(30, 41, 59));
            g2.setStroke(new BasicStroke(1.0f));
            int grooveStep = (int)(2.0 * scale); // 2-ft grooves
            for (int gy = ceilY + grooveStep; gy < plinthY; gy += grooveStep) {
                g2.drawLine(originX, gy, originX + bldgW, gy);
            }

            g2.setColor(isExport ? new Color(15, 23, 42) : new Color(56, 189, 248)); // Cyan boundary
            g2.setStroke(new BasicStroke(2.0f));
            g2.drawRect(originX, ceilY, bldgW, plinthY - ceilY);

            // 4. Doors & Windows projection (Strict Architectural Facade Visibility & Alignment)
            double lintelHtFt = 7.0;
            int lintelY = plinthY - (int)(lintelHtFt * scale);
            int visibleOpeningsCount = 0;

            for (CADElement el : elements) {
                boolean isDoor = "door".equals(el.type) || (el.type != null && el.type.startsWith("door-"));
                boolean isWin = el.type != null && el.type.contains("window");
                if (!isDoor && !isWin) continue;

                // Strict Facade Visibility Check: Only project openings that face this specific exterior facade!
                if (!isOpeningVisibleOnFacade(el, viewMode, walls)) continue;
                visibleOpeningsCount++;

                double cx = el.x + el.w / 2.0;
                double cy = el.y + el.h / 2.0;
                boolean isRotated90 = Math.abs(Math.sin(Math.toRadians(el.rotation))) > 0.7;
                double spanX = isRotated90 ? el.h : el.w;
                double spanY = isRotated90 ? el.w : el.h;

                // Compute plan position along chosen facade projection axis
                double elPlanPos = isXAxis ? (cx - minX) : (cy - minY);
                if (viewMode == 1) elPlanPos = (maxX - cx); // North facade (East on left, West on right)
                if (viewMode == 3) elPlanPos = (maxY - cy); // East facade (South on left, North on right)

                double elWidthFt = isXAxis ? (spanX / FT_PX) : (spanY / FT_PX);
                if (elWidthFt < 1.0) elWidthFt = 3.0; // Standard default

                int elX = originX + (int)((elPlanPos / FT_PX - elWidthFt / 2.0) * scale);
                int elW = Math.max(14, (int)(elWidthFt * scale));

                if (isDoor) {
                    int dTopY = lintelY; // Aligns strictly with architectural lintel band (+7'-0" from plinth)
                    int dH = plinthY - dTopY;

                    // Concrete Plinth Entrance Steps (Ground Level to Plinth Level transition)
                    int stepCount = 3;
                    int stepH = Math.max(3, (glY - plinthY) / stepCount);
                    for (int s = 0; s < stepCount; s++) {
                        int sY = plinthY + s * stepH;
                        int sPad = (s + 1) * Math.max(4, (int)(0.35 * scale)); // Step treads expand outward
                        int sLeft = elX - sPad;
                        int sW = elW + sPad * 2;
                        int sBot = (s == stepCount - 1) ? glY : (plinthY + (s + 1) * stepH);

                        g2.setColor(isExport ? new Color(226, 232, 240) : new Color(30, 41, 59));
                        g2.fillRect(sLeft, sY, sW, sBot - sY);
                        g2.setColor(isExport ? new Color(203, 213, 225) : new Color(51, 65, 85));
                        g2.drawLine(sLeft, sY, sLeft + sW, sY);
                        g2.setColor(isExport ? new Color(148, 163, 184) : new Color(71, 85, 105));
                        g2.setStroke(new BasicStroke(1.0f));
                        g2.drawRect(sLeft, sY, sW, sBot - sY);
                    }

                    // Door Casing / Architrave
                    g2.setColor(new Color(51, 65, 85));
                    g2.fillRect(elX - 2, dTopY - 2, elW + 4, dH + 2);

                    // Door Leaf (Warm Mahogany / Modern Slate)
                    g2.setColor(isExport ? new Color(120, 53, 15) : new Color(30, 41, 59));
                    g2.fillRect(elX, dTopY, elW, dH);
                    g2.setColor(new Color(245, 158, 11)); // Amber trim
                    g2.setStroke(new BasicStroke(1.2f));
                    g2.drawRect(elX, dTopY, elW, dH);

                    // Multi-Panel detailing
                    int pMidX = elX + elW / 2;
                    int pMidY = dTopY + dH / 2;
                    g2.drawRect(elX + 3, dTopY + 4, elW / 2 - 5, dH / 2 - 8);
                    g2.drawRect(pMidX + 2, dTopY + 4, elW / 2 - 5, dH / 2 - 8);
                    g2.drawRect(elX + 3, pMidY + 4, elW / 2 - 5, dH / 2 - 8);
                    g2.drawRect(pMidX + 2, pMidY + 4, elW / 2 - 5, dH / 2 - 8);

                    // Door Knob (Brass)
                    g2.setColor(new Color(251, 191, 36));
                    g2.fillOval(elX + elW - 8, dTopY + (int)(dH * 0.55), 4, 4);

                } else if (isWin) {
                    boolean isVent = el.type != null && el.type.contains("vent");
                    double winHtFt = isVent ? 2.0 : 4.0;
                    int wTopY = lintelY; // STRICT ARCHITECTURAL ALIGNMENT: Top of window matches door lintel!
                    int wH = Math.max(10, (int)(winHtFt * scale));
                    int wSillY = wTopY + wH;

                    // Cantilever RCC Weather shade / Chajja (extends 6" past window, 4" thick)
                    int chajjaExt = Math.max(6, (int)(0.5 * scale));
                    int chajjaThick = Math.max(3, (int)(0.35 * scale));
                    g2.setColor(isExport ? new Color(203, 213, 225) : new Color(148, 163, 184));
                    g2.fillRect(elX - chajjaExt, wTopY - chajjaThick, elW + chajjaExt * 2, chajjaThick);
                    g2.setColor(isExport ? new Color(100, 116, 139) : new Color(51, 65, 85));
                    g2.drawRect(elX - chajjaExt, wTopY - chajjaThick, elW + chajjaExt * 2, chajjaThick);

                    // Window Frame
                    g2.setColor(new Color(30, 41, 59));
                    g2.fillRect(elX, wTopY, elW, wH);

                    // Glass Pane (Sky Blue Reflection)
                    g2.setColor(new Color(2, 132, 199));
                    g2.fillRect(elX + 3, wTopY + 3, elW - 6, wH - 6);

                    // Center Mullion
                    g2.setColor(Color.WHITE);
                    g2.setStroke(new BasicStroke(1.0f));
                    g2.drawLine(elX + elW / 2, wTopY + 3, elX + elW / 2, wSillY - 3);
                    g2.drawRect(elX, wTopY, elW, wH);

                    // Concrete Sill
                    g2.setColor(new Color(148, 163, 184));
                    g2.fillRect(elX - 3, wSillY, elW + 6, 4);
                }
            }

            // Solid Wall Annotation if no exterior openings exist on this facade
            if (visibleOpeningsCount == 0) {
                g2.setColor(isExport ? new Color(148, 163, 184) : new Color(100, 116, 139, 160));
                g2.setFont(new Font("Segoe UI", Font.BOLD, 12));
                String note = "SOLID MASONRY FACADE (NO OPENINGS)";
                FontMetrics fm = g2.getFontMetrics();
                g2.drawString(note, originX + (bldgW - fm.stringWidth(note)) / 2, ceilY + (plinthY - ceilY) / 2);
            }

            // 5. RCC Ceiling Slab (6" RCC with architectural overhang)
            int slabOverhang = Math.max(8, (int)(0.75 * scale)); // 9" cornice overhang
            g2.setColor(isExport ? new Color(203, 213, 225) : new Color(30, 41, 59));
            g2.fillRect(originX - slabOverhang, slabY, bldgW + slabOverhang * 2, ceilY - slabY);
            g2.setColor(new Color(148, 163, 184));
            g2.drawRect(originX - slabOverhang, slabY, bldgW + slabOverhang * 2, ceilY - slabY);

            // 6. Terrace Parapet Wall
            g2.setColor(isExport ? new Color(241, 245, 249) : new Color(15, 23, 42));
            g2.fillRect(originX, parapetY, bldgW, slabY - parapetY);
            g2.setColor(new Color(56, 189, 248));
            g2.drawRect(originX, parapetY, bldgW, slabY - parapetY);

            // Parapet Coping Band
            g2.setColor(new Color(148, 163, 184));
            g2.fillRect(originX - 4, parapetY - 4, bldgW + 8, 4);

            // 7. Architectural Datums & Level Tags
            if (datums) {
                drawDatumTag(g2, originX - 40, parapetY, String.format("+%.1f' TOP OF PARAPET", parapetFt), isExport);
                drawDatumTag(g2, originX - 40, slabY, String.format("+%.1f' ROOF SLAB", slabFt), isExport);
                drawDatumTag(g2, originX - 40, ceilY, String.format("+%.1f' CEILING", ceilFt), isExport);
                drawDatumTag(g2, originX - 40, lintelY, String.format("+%.1f' LINTEL LEVEL", plinthFt + lintelHtFt), isExport);
                drawDatumTag(g2, originX - 40, plinthY, String.format("+%.1f' PLINTH", plinthFt), isExport);
                drawDatumTag(g2, originX - 40, glY, "±0.0' GROUND LEVEL", isExport);
            }

            // 8. Dimensions
            if (dims) {
                g2.setColor(new Color(56, 189, 248));
                g2.setFont(new Font("Consolas", Font.BOLD, 10));
                // Horizontal width
                int dimY = glY + 25;
                g2.drawLine(originX, dimY, originX + bldgW, dimY);
                g2.drawLine(originX, dimY - 4, originX, dimY + 4);
                g2.drawLine(originX + bldgW, dimY - 4, originX + bldgW, dimY + 4);
                String wText = formatImperial(facadeLenPx);
                FontMetrics fm = g2.getFontMetrics();
                g2.drawString(wText, originX + (bldgW - fm.stringWidth(wText)) / 2, dimY - 4);
            }

            // View Label Badge at bottom center
            g2.setColor(isExport ? Color.BLACK : Color.WHITE);
            g2.setFont(new Font("Segoe UI", Font.BOLD, 12));
            String titleText = currentView.toUpperCase() + " — 1:100 SCALE";
            FontMetrics fm = g2.getFontMetrics();
            g2.drawString(titleText, originX + (bldgW - fm.stringWidth(titleText)) / 2, glY + 50);
        }

        private boolean isOpeningVisibleOnFacade(CADElement el, int viewMode, List<Wall> wallList) {
            if (wallList == null || wallList.isEmpty()) return false;

            double cx = el.x + el.w / 2.0;
            double cy = el.y + el.h / 2.0;

            boolean isRotated90 = Math.abs(Math.sin(Math.toRadians(el.rotation))) > 0.7;
            double spanX = isRotated90 ? el.h : el.w;
            double spanY = isRotated90 ? el.w : el.h;
            boolean isHorizontalOpening = spanX >= spanY;

            // ViewMode: 0=South, 1=North, 2=West, 3=East
            if (viewMode == 0 || viewMode == 1) {
                if (!isHorizontalOpening) return false;

                if (viewMode == 0) { // South facade: looking from South towards North
                    for (Wall w : wallList) {
                        double minWx = Math.min(w.x1, w.x2);
                        double maxWx = Math.max(w.x1, w.x2);
                        if (cx >= minWx - 10.0 && cx <= maxWx + 10.0) {
                            double wy = (w.y1 + w.y2) / 2.0;
                            if (wy > cy + 15.0) return false; // Blocked by wall further south
                        }
                    }
                    return true;
                } else { // North facade: looking from North towards South
                    for (Wall w : wallList) {
                        double minWx = Math.min(w.x1, w.x2);
                        double maxWx = Math.max(w.x1, w.x2);
                        if (cx >= minWx - 10.0 && cx <= maxWx + 10.0) {
                            double wy = (w.y1 + w.y2) / 2.0;
                            if (wy < cy - 15.0) return false; // Blocked by wall further north
                        }
                    }
                    return true;
                }
            } else {
                if (isHorizontalOpening) return false;

                if (viewMode == 2) { // West elevation: looking from West towards East
                    for (Wall w : wallList) {
                        double minWy = Math.min(w.y1, w.y2);
                        double maxWy = Math.max(w.y1, w.y2);
                        if (cy >= minWy - 10.0 && cy <= maxWy + 10.0) {
                            double wx = (w.x1 + w.x2) / 2.0;
                            if (wx < cx - 15.0) return false; // Blocked by wall further west
                        }
                    }
                    return true;
                } else { // East elevation: looking from East towards West
                    for (Wall w : wallList) {
                        double minWy = Math.min(w.y1, w.y2);
                        double maxWy = Math.max(w.y1, w.y2);
                        if (cy >= minWy - 10.0 && cy <= maxWy + 10.0) {
                            double wx = (w.x1 + w.x2) / 2.0;
                            if (wx > cx + 15.0) return false; // Blocked by wall further east
                        }
                    }
                    return true;
                }
            }
        }

        private void drawDatumTag(Graphics2D g2, int x, int y, String label, boolean isExport) {
            g2.setColor(new Color(245, 158, 11)); // Amber level indicator
            g2.setStroke(new BasicStroke(1.2f));
            Polygon poly = new Polygon();
            poly.addPoint(x, y);
            poly.addPoint(x - 8, y - 5);
            poly.addPoint(x - 8, y + 5);
            g2.fill(poly);

            g2.setColor(new Color(148, 163, 184));
            g2.drawLine(x, y, x + 35, y);

            g2.setFont(new Font("Consolas", Font.BOLD, 9));
            g2.setColor(isExport ? Color.DARK_GRAY : new Color(203, 213, 225));
            g2.drawString(label, x - 130, y + 3);
        }
    }

    /**
     * Architectural Sectional Elevation Cut Engine & Live Interactive Viewer Dialog:
     * Cuts the 2D architectural plan along the section line S = [P1, P2].
     * Computes cutting-plane intersections and projects walls, doors, windows,
     * structural ceiling slab, parapet, plinth, and realistic 2D elevations of
     * bathroom fixtures (wash basin, toilet WC, bathtub, shower) and kitchen casework
     * (countertops, base cabinets, wall upper cabinets, stove/cooktop, sink).
     */
    public void showSectionalElevationDialog(CADElement sectionTag) {
        if (sectionTag == null || sectionTag.points == null || sectionTag.points.size() < 2) {
            JOptionPane.showMessageDialog(this, "Please select or create a valid Section Tag first.", "Section Tag Required", JOptionPane.WARNING_MESSAGE);
            return;
        }

        Point2D.Double p1 = sectionTag.points.get(0);
        Point2D.Double p2 = sectionTag.points.get(1);
        double cutLengthPx = p1.distance(p2);
        if (cutLengthPx < 1.0 * FT_PX) {
            JOptionPane.showMessageDialog(this, "Section cut line is too short to generate an elevation.", "Invalid Section", JOptionPane.WARNING_MESSAGE);
            return;
        }

        JDialog dlg = new JDialog(this, "Architectural Sectional Elevation — " + sectionTag.name, true);
        dlg.setLayout(new BorderLayout());
        dlg.getContentPane().setBackground(new Color(15, 23, 42));

        // Options panel at top
        JPanel topBar = new JPanel(new FlowLayout(FlowLayout.LEFT, 12, 8));
        topBar.setBackground(new Color(24, 33, 53));
        topBar.setBorder(BorderFactory.createMatteBorder(0, 0, 1, 0, new Color(51, 65, 85)));

        JLabel titleLbl = new JLabel("SECTION: " + sectionTag.name);
        titleLbl.setFont(new Font("Segoe UI", Font.BOLD, 13));
        titleLbl.setForeground(new Color(245, 158, 11)); // Amber
        topBar.add(titleLbl);

        topBar.add(new JSeparator(JSeparator.VERTICAL));

        JLabel hLbl = new JLabel("Ceiling Height:");
        hLbl.setFont(new Font("Segoe UI", Font.PLAIN, 11));
        hLbl.setForeground(new Color(203, 213, 225));
        topBar.add(hLbl);

        JComboBox<String> heightCombo = new JComboBox<>(new String[]{"10'-0\" (Standard High)", "9'-0\" (Compact Standard)", "11'-0\" (Grand Ceiling)"});
        styleComboBox(heightCombo);
        topBar.add(heightCombo);

        JCheckBox showDimsBox = new JCheckBox("Show Level Datums & Dimensions", true);
        showDimsBox.setFont(new Font("Segoe UI", Font.PLAIN, 11));
        showDimsBox.setForeground(new Color(203, 213, 225));
        showDimsBox.setOpaque(false);
        topBar.add(showDimsBox);

        JCheckBox showFixturesBox = new JCheckBox("Show Fixtures & Casework (Bath/Kitchen)", true);
        showFixturesBox.setFont(new Font("Segoe UI", Font.PLAIN, 11));
        showFixturesBox.setForeground(new Color(203, 213, 225));
        showFixturesBox.setOpaque(false);
        topBar.add(showFixturesBox);

        dlg.add(topBar, BorderLayout.NORTH);

        // Center live elevation drawing canvas
        final double[] customCeilFt = new double[]{10.0};
        JPanel elevationCanvas = new JPanel() {
            @Override
            protected void paintComponent(Graphics g) {
                super.paintComponent(g);
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
                g2.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);

                renderSectionalElevationCut(g2, getWidth(), getHeight(), sectionTag,
                        customCeilFt[0], showDimsBox.isSelected(), showFixturesBox.isSelected(), false);
                g2.dispose();
            }
        };
        elevationCanvas.setBackground(new Color(11, 15, 25));
        elevationCanvas.setPreferredSize(new Dimension(980, 560));
        dlg.add(elevationCanvas, BorderLayout.CENTER);

        heightCombo.addActionListener(e -> {
            int idx = heightCombo.getSelectedIndex();
            customCeilFt[0] = (idx == 0 ? 10.0 : (idx == 1 ? 9.0 : 11.0));
            elevationCanvas.repaint();
        });
        showDimsBox.addActionListener(e -> elevationCanvas.repaint());
        showFixturesBox.addActionListener(e -> elevationCanvas.repaint());

        // Bottom Action Bar
        JPanel botBar = new JPanel(new FlowLayout(FlowLayout.RIGHT, 10, 10));
        botBar.setBackground(new Color(15, 23, 42));
        botBar.setBorder(BorderFactory.createMatteBorder(1, 0, 0, 0, new Color(30, 41, 59)));

        ModernButton exportPngBtn = new ModernButton("Export Section (PNG)", new Color(24, 33, 53), Color.WHITE, new Color(51, 65, 85));
        exportPngBtn.setPreferredSize(new Dimension(160, 32));
        exportPngBtn.addActionListener(e -> {
            JFileChooser fc = new JFileChooser();
            fc.setSelectedFile(new File("Section_" + sectionTag.name.replace(" ", "_").replace("'", "") + "_Elevation.png"));
            if (fc.showSaveDialog(dlg) == JFileChooser.APPROVE_OPTION) {
                File f = fc.getSelectedFile();
                if (!f.getName().toLowerCase().endsWith(".png")) f = new File(f.getParentFile(), f.getName() + ".png");
                try {
                    BufferedImage bImg = new BufferedImage(1920, 1080, BufferedImage.TYPE_INT_ARGB);
                    Graphics2D g2 = bImg.createGraphics();
                    g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                    g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
                    renderSectionalElevationCut(g2, 1920, 1080, sectionTag, customCeilFt[0], showDimsBox.isSelected(), showFixturesBox.isSelected(), true);
                    g2.dispose();
                    javax.imageio.ImageIO.write(bImg, "png", f);
                    JOptionPane.showMessageDialog(dlg, "Sectional elevation saved to:\n" + f.getAbsolutePath(), "Export Successful", JOptionPane.INFORMATION_MESSAGE);
                } catch (Exception ex) {
                    JOptionPane.showMessageDialog(dlg, "Error saving section image: " + ex.getMessage(), "Export Failed", JOptionPane.ERROR_MESSAGE);
                }
            }
        });

        ModernButton closeBtn = new ModernButton("Close", new Color(14, 116, 144), Color.WHITE, new Color(56, 189, 248));
        closeBtn.setPreferredSize(new Dimension(90, 32));
        closeBtn.addActionListener(e -> dlg.dispose());

        botBar.add(exportPngBtn);
        botBar.add(closeBtn);
        dlg.add(botBar, BorderLayout.SOUTH);

        dlg.pack();
        dlg.setLocationRelativeTo(this);
        dlg.setVisible(true);
    }

    /**
     * Core Architectural Section Cut Computation & 2D Vector Rendering Routine:
     * Projects plan-space intersections onto 2D elevation coordinate space.
     */
    public void renderSectionalElevationCut(Graphics2D g2, int canvasW, int canvasH, CADElement sectionTag,
                                           double ceilingHeightFt, boolean showDatums, boolean showFixtures, boolean isHighResExport) {
        // Background
        g2.setColor(isHighResExport ? Color.WHITE : new Color(11, 15, 25));
        g2.fillRect(0, 0, canvasW, canvasH);

        Point2D.Double p1 = sectionTag.points.get(0);
        Point2D.Double p2 = sectionTag.points.get(1);
        double cutLengthPx = p1.distance(p2);
        if (cutLengthPx < 1.0) return;

        double cutLengthFt = cutLengthPx / FT_PX;
        double dx = p2.x - p1.x, dy = p2.y - p1.y;
        double ux = dx / cutLengthPx, uy = dy / cutLengthPx;   // Unit vector along cut line
        double nx = -uy, ny = ux;                              // Unit normal vector (sight direction)

        // Architectural Vertical Z Datum Heights (all in feet relative to GL = 0'-0")
        double glFt = 0.0;
        double plinthFt = 1.5;                                // Plinth Level = +1'-6"
        double floorFt = plinthFt;
        double ceilingFt = floorFt + ceilingHeightFt;         // e.g. 1.5 + 10.0 = +11'-6"
        double slabFt = ceilingFt + 0.5;                      // Roof Slab 6" RCC = +12'-0"
        double parapetFt = slabFt + 3.0;                      // Parapet Wall = +15'-0"
        double foundationDepthFt = 3.0;                       // Below ground level = -3'-0"
        double totalHeightFt = parapetFt + foundationDepthFt + 1.0;

        // Viewport layout margins
        int leftPad = isHighResExport ? 160 : 100;
        int rightPad = isHighResExport ? 160 : 90;
        int topPad = isHighResExport ? 120 : 70;
        int botPad = isHighResExport ? 120 : 70;

        int drawAreaW = canvasW - leftPad - rightPad;
        int drawAreaH = canvasH - topPad - botPad;
        if (drawAreaW <= 50 || drawAreaH <= 50) return;

        double scaleX = drawAreaW / Math.max(12.0, cutLengthFt);
        double scaleY = drawAreaH / Math.max(16.0, totalHeightFt);
        double scale = Math.min(scaleX, scaleY);

        int originX = leftPad + (int)((drawAreaW - cutLengthFt * scale) / 2.0);
        // Base ground level Y on canvas
        int glY = canvasH - botPad - (int)(foundationDepthFt * scale);
        int plY = glY - (int)(plinthFt * scale);
        int ceilY = glY - (int)(ceilingFt * scale);
        int slabY = glY - (int)(slabFt * scale);
        int parapetY = glY - (int)(parapetFt * scale);
        int fdnY = glY + (int)(foundationDepthFt * scale);

        Color cGround = isHighResExport ? new Color(120, 113, 108) : new Color(71, 85, 105);
        Color cCutWall = isHighResExport ? new Color(30, 41, 59) : new Color(56, 189, 248);
        Color cWallHatch = isHighResExport ? new Color(71, 85, 105) : new Color(14, 116, 144);
        Color cBgWall = isHighResExport ? new Color(241, 245, 249) : new Color(15, 23, 42);
        Color cLine = isHighResExport ? Color.BLACK : new Color(226, 232, 240);
        Color cSlab = isHighResExport ? new Color(203, 213, 225) : new Color(30, 41, 59);
        Color cText = isHighResExport ? new Color(15, 23, 42) : new Color(241, 245, 249);
        Color cAmber = new Color(245, 158, 11);
        Color cCyan = new Color(56, 189, 248);

        // ─── 1. Background Wall Elevation Envelope ───
        int secWidthPx = (int)(cutLengthFt * scale);
        g2.setColor(cBgWall);
        g2.fillRect(originX, ceilY, secWidthPx, plY - ceilY);

        // ─── 2. Plinth & Ground Mass ───
        // Earth / Sub-base hatch below GL
        g2.setColor(isHighResExport ? new Color(245, 245, 244) : new Color(15, 20, 30));
        g2.fillRect(originX - 30, glY, secWidthPx + 60, fdnY - glY);

        // Ground Level thick baseline
        g2.setColor(cGround);
        g2.setStroke(new BasicStroke(isHighResExport ? 3.0f : 2.2f));
        g2.drawLine(originX - 40, glY, originX + secWidthPx + 40, glY);

        // Plinth masonry base
        g2.setColor(cSlab);
        g2.fillRect(originX, plY, secWidthPx, glY - plY);
        g2.setColor(cLine);
        g2.setStroke(new BasicStroke(1.5f));
        g2.drawRect(originX, plY, secWidthPx, glY - plY);

        // ─── 3. Roof RCC Slab & Parapet Terrace ───
        // Concrete roof slab (6" RCC)
        g2.setColor(cSlab);
        g2.fillRect(originX - 10, slabY, secWidthPx + 20, ceilY - slabY);
        g2.setColor(cLine);
        g2.setStroke(new BasicStroke(1.8f));
        g2.drawRect(originX - 10, slabY, secWidthPx + 20, ceilY - slabY);

        // Parapet walls on terrace (3'-0" high)
        int paraThickPx = Math.max(6, (int)(0.75 * scale)); // 9" parapet
        g2.setColor(cSlab);
        g2.fillRect(originX, parapetY, paraThickPx, slabY - parapetY);
        g2.fillRect(originX + secWidthPx - paraThickPx, parapetY, paraThickPx, slabY - parapetY);
        g2.setColor(cLine);
        g2.drawRect(originX, parapetY, paraThickPx, slabY - parapetY);
        g2.drawRect(originX + secWidthPx - paraThickPx, parapetY, paraThickPx, slabY - parapetY);

        // Coping stones on parapet tops
        g2.setColor(cAmber);
        g2.fillRect(originX - 2, parapetY - 4, paraThickPx + 4, 4);
        g2.fillRect(originX + secWidthPx - paraThickPx - 2, parapetY - 4, paraThickPx + 4, 4);

        // ─── 4. Cut Walls (Cutting Plane Intersections with Wall Segments) ───
        List<Double> cutWallXList = new ArrayList<>();
        for (Wall w : walls) {
            Point2D.Double cross = computeSegmentIntersection(p1.x, p1.y, p2.x, p2.y, w.x1, w.y1, w.x2, w.y2);
            if (cross != null) {
                double distAlong = (cross.x - p1.x) * ux + (cross.y - p1.y) * uy;
                double distFt = distAlong / FT_PX;
                double wThickFt = w.thicknessInches / 12.0;
                int wx = originX + (int)(distFt * scale);
                int wpx = Math.max(6, (int)(wThickFt * scale));
                int leftX = wx - wpx / 2;

                cutWallXList.add((double) wx);

                // Cut wall vertical column from Plinth to Ceiling
                g2.setColor(cBgWall);
                g2.fillRect(leftX, ceilY, wpx, plY - ceilY);

                // ANSI31 45° Brick Hatch pattern inside cut wall
                Shape oldClip = g2.getClip();
                g2.clipRect(leftX, ceilY, wpx, plY - ceilY);
                g2.setColor(cWallHatch);
                g2.setStroke(new BasicStroke(0.9f));
                int hatchStep = 8;
                for (int hx = leftX - (plY - ceilY); hx < leftX + wpx + (plY - ceilY); hx += hatchStep) {
                    g2.drawLine(hx, plY, hx + (plY - ceilY), ceilY);
                }
                g2.setClip(oldClip);

                // Cut wall boundary outline (Heavy cut lines)
                g2.setColor(cCutWall);
                g2.setStroke(new BasicStroke(isHighResExport ? 2.5f : 1.8f));
                g2.drawRect(leftX, ceilY, wpx, plY - ceilY);

                // Wall foundation below ground
                int fdnW = (int)(wpx * 2.2);
                int fdnLeft = wx - fdnW / 2;
                g2.setColor(cSlab);
                g2.fillRect(fdnLeft, glY, fdnW, fdnY - glY);
                g2.setColor(cLine);
                g2.drawRect(fdnLeft, glY, fdnW, fdnY - glY);
            }
        }

        // ─── 5. Openings (Doors & Windows Cut or in Background Elevation) ───
        for (CADElement el : elements) {
            if (!el.isOpening()) continue;
            double cx = el.x + el.w / 2.0, cy = el.y + el.h / 2.0;
            double projAlong = (cx - p1.x) * ux + (cy - p1.y) * uy;
            double perpDist = (cx - p1.x) * nx + (cy - p1.y) * ny; // distance in sight direction

            // If close to cut line or in background sight view (within 14 ft depth)
            if (projAlong >= 0 && projAlong <= cutLengthPx && perpDist >= -1.0 * FT_PX && perpDist <= 14.0 * FT_PX) {
                double distFt = projAlong / FT_PX;
                double openWidthFt = el.w / FT_PX;
                int ox = originX + (int)(distFt * scale);
                int ow = Math.max(12, (int)(openWidthFt * scale));
                int leftX = ox - ow / 2;

                if (el.isDoor() || el.isWallOpening()) {
                    // Standard Door Opening: 7'-0" height above plinth
                    int doorH = (int)(7.0 * scale);
                    int doorTopY = plY - doorH;

                    // Clear passage / opening
                    g2.setColor(isHighResExport ? new Color(250, 250, 250) : new Color(18, 26, 43));
                    g2.fillRect(leftX, doorTopY, ow, doorH);

                    // Door frame & architrave trim
                    g2.setColor(cLine);
                    g2.setStroke(new BasicStroke(1.2f));
                    g2.drawRect(leftX, doorTopY, ow, doorH);

                    if (el.isDoor()) {
                        // Door leaf panels and handle
                        int framePad = Math.max(2, (int)(0.2 * scale));
                        g2.drawRect(leftX + framePad, doorTopY + framePad, ow - framePad * 2, doorH - framePad);
                        int handleY = plY - (int)(3.0 * scale); // 3'-0" handle height
                        g2.setColor(cAmber);
                        g2.fillOval(leftX + ow - framePad - 8, handleY, 5, 5);
                    }

                    // Lintel beam indicator above door (7' to 7'-9")
                    g2.setColor(cLine);
                    g2.setStroke(new BasicStroke(0.8f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 10, new float[]{4, 4}, 0));
                    g2.drawLine(leftX - 4, doorTopY, leftX + ow + 4, doorTopY);

                } else if (el.isWindow()) {
                    // Standard Window: Sill at 3'-0" above plinth, Lintel at 7'-0" (4' high window)
                    int sillY = plY - (int)(3.0 * scale);
                    int lintelY = plY - (int)(7.0 * scale);
                    int winH = sillY - lintelY;

                    // Window glass tint
                    g2.setColor(isHighResExport ? new Color(224, 242, 254) : new Color(14, 116, 144, 70));
                    g2.fillRect(leftX, lintelY, ow, winH);

                    // Outer window frame
                    g2.setColor(cLine);
                    g2.setStroke(new BasicStroke(1.4f));
                    g2.drawRect(leftX, lintelY, ow, winH);

                    // Mullions / Casement mullion divide
                    g2.drawLine(leftX + ow / 2, lintelY, leftX + ow / 2, sillY);
                    g2.drawLine(leftX, lintelY + winH / 2, leftX + ow, lintelY + winH / 2);

                    // Window sill projection (extended ledge)
                    g2.setColor(cCyan);
                    g2.setStroke(new BasicStroke(2.0f));
                    g2.drawLine(leftX - 4, sillY, leftX + ow + 4, sillY);
                }
            }
        }

        // ─── 6. Realistic 2D Elevation Silhouettes for Bath & Kitchen Fixtures ───
        if (showFixtures) {
            for (CADElement el : elements) {
                if (el.isOpening() || "tag".equals(el.type) || "north-arrow".equals(el.type) || "section-tag".equals(el.type)) continue;

                double cx = el.x + el.w / 2.0, cy = el.y + el.h / 2.0;
                double projAlong = (cx - p1.x) * ux + (cy - p1.y) * uy;
                double perpDist = (cx - p1.x) * nx + (cy - p1.y) * ny; // distance in sight direction

                // Within longitudinal cut span and within visible room depth (0 to 8 ft)
                if (projAlong >= 0 && projAlong <= cutLengthPx && perpDist >= -1.0 * FT_PX && perpDist <= 8.0 * FT_PX) {
                    double distFt = projAlong / FT_PX;
                    int ox = originX + (int)(distFt * scale);
                    String type = el.type;

                    // ════ BATHROOM FIXTURES ════
                    if (type.equals("toilet")) {
                        // Toilet WC Elevation (Bowl rim at 1'-4", Cistern tank at 2'-6")
                        int wcW = Math.max(14, (int)(1.67 * scale));
                        int wx = ox - wcW / 2;
                        int rimY = plY - (int)(1.33 * scale);
                        int tankTopY = plY - (int)(2.6 * scale);
                        int tankW = (int)(wcW * 0.85);
                        int tankX = ox - tankW / 2;

                        // Cistern tank
                        g2.setColor(isHighResExport ? Color.WHITE : new Color(241, 245, 249));
                        g2.fillRoundRect(tankX, tankTopY, tankW, rimY - tankTopY, 4, 4);
                        g2.setColor(cLine);
                        g2.setStroke(new BasicStroke(1.2f));
                        g2.drawRoundRect(tankX, tankTopY, tankW, rimY - tankTopY, 4, 4);

                        // Flush button
                        g2.setColor(cAmber);
                        g2.drawOval(ox - 3, tankTopY + 3, 6, 4);

                        // WC bowl base & seat
                        g2.setColor(isHighResExport ? Color.WHITE : new Color(241, 245, 249));
                        g2.fillRoundRect(wx, rimY, wcW, plY - rimY, 6, 6);
                        g2.setColor(cLine);
                        g2.drawRoundRect(wx, rimY, wcW, plY - rimY, 6, 6);
                        g2.setColor(cCyan);
                        g2.drawRect(wx + 2, rimY - 2, wcW - 4, 3); // toilet seat lid

                    } else if (type.equals("basin")) {
                        // Wash Basin / Vanity Elevation (Counter rim at 2'-8", Mirror at 3'-6" to 6'-6")
                        int basW = Math.max(18, (int)(2.5 * scale));
                        int bx = ox - basW / 2;
                        int rimY = plY - (int)(2.67 * scale); // 2'-8"
                        int basH = (int)(0.8 * scale);

                        // Vanity under-counter cabinet / pedestal
                        g2.setColor(isHighResExport ? new Color(241, 245, 249) : new Color(24, 33, 53));
                        g2.fillRect(bx + 2, rimY + basH, basW - 4, plY - (rimY + basH));
                        g2.setColor(cLine);
                        g2.setStroke(new BasicStroke(1.2f));
                        g2.drawRect(bx + 2, rimY + basH, basW - 4, plY - (rimY + basH));
                        // Cabinet door line & knob
                        g2.drawLine(ox, rimY + basH, ox, plY);
                        g2.fillOval(ox - 5, rimY + basH + (plY - rimY - basH) / 2, 3, 3);
                        g2.fillOval(ox + 3, rimY + basH + (plY - rimY - basH) / 2, 3, 3);

                        // Ceramic Basin bowl
                        g2.setColor(isHighResExport ? Color.WHITE : new Color(248, 250, 252));
                        g2.fillRoundRect(bx, rimY, basW, basH, 6, 6);
                        g2.setColor(cLine);
                        g2.drawRoundRect(bx, rimY, basW, basH, 6, 6);

                        // Faucet / Mixer Tap
                        g2.setColor(cAmber);
                        g2.setStroke(new BasicStroke(1.8f));
                        g2.drawLine(ox, rimY, ox, rimY - (int)(0.4 * scale));
                        g2.drawLine(ox, rimY - (int)(0.4 * scale), ox + 5, rimY - (int)(0.35 * scale));

                        // Overhead Bathroom Mirror (3'-6" to 6'-0")
                        int mirBotY = plY - (int)(3.5 * scale);
                        int mirTopY = plY - (int)(6.0 * scale);
                        int mirW = (int)(basW * 0.9);
                        g2.setColor(isHighResExport ? new Color(224, 242, 254) : new Color(56, 189, 248, 50));
                        g2.fillRect(ox - mirW / 2, mirTopY, mirW, mirBotY - mirTopY);
                        g2.setColor(cLine);
                        g2.setStroke(new BasicStroke(1.2f));
                        g2.drawRect(ox - mirW / 2, mirTopY, mirW, mirBotY - mirTopY);

                    } else if (type.equals("bathtub")) {
                        // Bathtub Elevation (Rim at 1'-8" / 20" above floor, 5'-0" wide)
                        int tubW = Math.max(30, (int)(5.0 * scale));
                        int tx = ox - tubW / 2;
                        int rimY = plY - (int)(1.67 * scale); // 1'-8"

                        g2.setColor(isHighResExport ? Color.WHITE : new Color(241, 245, 249));
                        g2.fillRoundRect(tx, rimY, tubW, plY - rimY, 8, 8);
                        g2.setColor(cLine);
                        g2.setStroke(new BasicStroke(1.5f));
                        g2.drawRoundRect(tx, rimY, tubW, plY - rimY, 8, 8);

                        // Tub rim trim & shower mixer
                        g2.setColor(cCyan);
                        g2.drawLine(tx - 2, rimY, tx + tubW + 2, rimY);
                        g2.setColor(cAmber);
                        g2.drawLine(tx + 8, rimY, tx + 8, rimY - (int)(0.5 * scale));

                    } else if (type.equals("shower")) {
                        // Shower Stall (Glass partition enclosure 6'-6" high)
                        int shwW = Math.max(22, (int)(3.0 * scale));
                        int sx = ox - shwW / 2;
                        int shwTopY = plY - (int)(6.5 * scale);

                        g2.setColor(isHighResExport ? new Color(240, 249, 255) : new Color(14, 116, 144, 40));
                        g2.fillRect(sx, shwTopY, shwW, plY - shwTopY);
                        g2.setColor(cCyan);
                        g2.setStroke(new BasicStroke(1.2f));
                        g2.drawRect(sx, shwTopY, shwW, plY - shwTopY);

                        // Overhead rain shower head
                        g2.setColor(cAmber);
                        g2.setStroke(new BasicStroke(2.0f));
                        g2.drawLine(sx + shwW / 2, shwTopY, sx + shwW / 2, shwTopY + 14);
                        g2.drawLine(sx + shwW / 2 - 8, shwTopY + 14, sx + shwW / 2 + 8, shwTopY + 14);

                    // ════ KITCHEN FIXTURES & CASEWORK ════
                    } else if (type.startsWith("kitchen") || type.equals("stove") || type.equals("fridge")) {
                        // Standard Kitchen Ergonomics:
                        // Base Cabinet / Countertop: 2'-10" (34") above plinth
                        // Backsplash / Mid-zone: 2'-10" to 4'-6"
                        // Upper Wall Mounted Overhead Cabinets: 4'-6" to 7'-0"
                        int baseH = (int)(2.83 * scale); // 2'-10"
                        int baseTopY = plY - baseH;
                        int wallCabTopY = plY - (int)(7.0 * scale);
                        int wallCabBotY = plY - (int)(4.5 * scale);

                        if (type.equals("fridge")) {
                            // Refrigerator Elevation (6'-0" tall appliance)
                            int fW = Math.max(18, (int)(2.5 * scale));
                            int fx = ox - fW / 2;
                            int fTopY = plY - (int)(6.0 * scale);

                            g2.setColor(isHighResExport ? new Color(241, 245, 249) : new Color(30, 41, 59));
                            g2.fillRoundRect(fx, fTopY, fW, plY - fTopY, 6, 6);
                            g2.setColor(cLine);
                            g2.setStroke(new BasicStroke(1.5f));
                            g2.drawRoundRect(fx, fTopY, fW, plY - fTopY, 6, 6);

                            // Freezer / Fridge door split line & handles
                            int splitY = fTopY + (plY - fTopY) / 3;
                            g2.drawLine(fx, splitY, fx + fW, splitY);
                            g2.setColor(cAmber);
                            g2.drawLine(fx + fW - 4, fTopY + 8, fx + fW - 4, splitY - 8);
                            g2.drawLine(fx + fW - 4, splitY + 8, fx + fW - 4, plY - 14);

                        } else {
                            // Kitchen counter run / module
                            double elemWidthFt = Math.max(2.0, el.w / FT_PX);
                            int kw = Math.max(20, (int)(elemWidthFt * scale));
                            int kx = ox - kw / 2;

                            // 1. Base Cabinets with drawers & doors
                            g2.setColor(isHighResExport ? new Color(248, 250, 252) : new Color(24, 33, 53));
                            g2.fillRect(kx, baseTopY, kw, baseH);

                            // Granite countertop slab (1.5" bullnose overhang)
                            g2.setColor(isHighResExport ? new Color(71, 85, 105) : new Color(56, 189, 248));
                            g2.fillRect(kx - 2, baseTopY, kw + 4, Math.max(3, (int)(0.125 * scale)));

                            g2.setColor(cLine);
                            g2.setStroke(new BasicStroke(1.2f));
                            g2.drawRect(kx, baseTopY, kw, baseH);

                            // Base cabinet door divisions & drawer lines
                            int modules = Math.max(1, (int) Math.round(elemWidthFt / 2.0));
                            int modW = kw / modules;
                            int drawerH = Math.max(10, (int)(0.6 * scale));
                            for (int m = 0; m < modules; m++) {
                                int mx = kx + m * modW;
                                g2.setColor(cLine);
                                g2.setStroke(new BasicStroke(0.8f));
                                g2.drawRect(mx + 2, baseTopY + 5, modW - 4, drawerH); // cutlery drawer
                                g2.drawRect(mx + 2, baseTopY + drawerH + 7, modW - 4, baseH - drawerH - 12); // door
                                // Sleek metal handle
                                g2.setColor(cAmber);
                                g2.drawLine(mx + modW / 2 - 8, baseTopY + 5 + drawerH / 2, mx + modW / 2 + 8, baseTopY + 5 + drawerH / 2);
                                g2.drawLine(mx + modW - 8, baseTopY + drawerH + 16, mx + modW - 8, baseTopY + drawerH + 32);
                            }

                            // 2. Cooktop or Sink fixture on counter if applicable
                            if (type.contains("sink")) {
                                g2.setColor(cAmber);
                                g2.setStroke(new BasicStroke(2.0f));
                                g2.drawLine(ox, baseTopY, ox, baseTopY - (int)(0.6 * scale));
                                g2.drawLine(ox, baseTopY - (int)(0.6 * scale), ox + 8, baseTopY - (int)(0.5 * scale));
                            } else if (type.contains("stove") || type.equals("kitchen-compact") || type.equals("kitchen-linear")) {
                                // Stainless steel cooktop burners + Chimney hood overhead
                                g2.setColor(cAmber);
                                g2.fillRect(ox - 10, baseTopY - 4, 20, 4);
                                // Chimney exhaust hood overhead (at 5'-6" to 7'-0")
                                int chimW = Math.max(18, (int)(2.5 * scale));
                                int chimX = ox - chimW / 2;
                                int chimBotY = plY - (int)(5.5 * scale);
                                Polygon chimHood = new Polygon(
                                        new int[]{chimX, chimX + chimW, chimX + chimW - 8, chimX + 8},
                                        new int[]{chimBotY, chimBotY, wallCabTopY, wallCabTopY}, 4);
                                g2.setColor(isHighResExport ? new Color(203, 213, 225) : new Color(51, 65, 85));
                                g2.fillPolygon(chimHood);
                                g2.setColor(cLine);
                                g2.drawPolygon(chimHood);
                            }

                            // 3. Wall Mounted Overhead Upper Cabinets (4'-6" to 7'-0")
                            int wallCabH = wallCabBotY - wallCabTopY;
                            g2.setColor(isHighResExport ? new Color(241, 245, 249) : new Color(30, 41, 59));
                            g2.fillRect(kx, wallCabTopY, kw, wallCabH);
                            g2.setColor(cLine);
                            g2.setStroke(new BasicStroke(1.2f));
                            g2.drawRect(kx, wallCabTopY, kw, wallCabH);

                            for (int m = 0; m < modules; m++) {
                                int mx = kx + m * modW;
                                g2.drawRect(mx + 2, wallCabTopY + 3, modW - 4, wallCabH - 6);
                                g2.setColor(cAmber);
                                g2.fillOval(mx + modW - 8, wallCabBotY - 14, 3, 3);
                            }
                        }
                    }
                }
            }
        }

        // ─── 7. Architectural Level Datums, Labels & Imperial Dimensions ───
        if (showDatums) {
            drawArchitecturalLevelDatum(g2, originX + secWidthPx + 15, glY, "±0'-0\" GROUND LEVEL (GL)", isHighResExport);
            drawArchitecturalLevelDatum(g2, originX + secWidthPx + 15, plY, "+1'-6\" PLINTH LEVEL (PL)", isHighResExport);
            drawArchitecturalLevelDatum(g2, originX + secWidthPx + 15, plY - (int)(7.0 * scale), "+8'-6\" LINTEL LEVEL", isHighResExport);
            drawArchitecturalLevelDatum(g2, originX + secWidthPx + 15, ceilY, String.format("+%d'-6\" CEILING LEVEL", (int)(1.5 + ceilingHeightFt)), isHighResExport);
            drawArchitecturalLevelDatum(g2, originX + secWidthPx + 15, slabY, String.format("+%d'-0\" ROOF SLAB TOP", (int)(2.0 + ceilingHeightFt)), isHighResExport);
            drawArchitecturalLevelDatum(g2, originX + secWidthPx + 15, parapetY, String.format("+%d'-0\" PARAPET LVL", (int)(5.0 + ceilingHeightFt)), isHighResExport);

            // Left side overall clear room height vertical dimension (Plinth to Ceiling)
            int dimX = originX - 35;
            g2.setColor(cCyan);
            g2.setStroke(new BasicStroke(1.2f));
            g2.drawLine(dimX, plY, dimX, ceilY);
            // End ticks
            g2.drawLine(dimX - 5, plY, dimX + 5, plY);
            g2.drawLine(dimX - 5, ceilY, dimX + 5, ceilY);

            // Dimension text rotated vertical
            String hText = String.format("%.0f'-0\" CLEAR CEILING HEIGHT", ceilingHeightFt);
            g2.setFont(new Font("Consolas", Font.BOLD, isHighResExport ? 12 : 10));
            AffineTransform oldT = g2.getTransform();
            g2.translate(dimX - 8, (plY + ceilY) / 2);
            g2.rotate(-Math.PI / 2.0);
            FontMetrics fmh = g2.getFontMetrics();
            g2.drawString(hText, -fmh.stringWidth(hText) / 2, 0);
            g2.setTransform(oldT);
        }

        // ─── 8. Section Title & Drawing Scale Badge ───
        g2.setFont(new Font("Segoe UI", Font.BOLD, isHighResExport ? 16 : 13));
        g2.setColor(cText);
        String titleStr = "SECTIONAL ELEVATION " + sectionTag.name.toUpperCase();
        g2.drawString(titleStr, originX, topPad - 20);

        g2.setFont(new Font("Consolas", Font.PLAIN, isHighResExport ? 12 : 10));
        g2.setColor(cAmber);
        String scaleStr = String.format("CUT SPAN: %.1f FT  |  CEILING HT: %.1f FT  |  HDE CAD STUDIO", cutLengthFt, ceilingHeightFt);
        g2.drawString(scaleStr, originX, topPad - 4);
    }

    private void drawArchitecturalLevelDatum(Graphics2D g2, int x, int y, String label, boolean isHighRes) {
        g2.setColor(new Color(245, 158, 11)); // Amber level datum
        g2.setStroke(new BasicStroke(1.2f));
        g2.drawLine(x, y, x + 15, y);

        // AutoCAD style level datum symbol (inverted triangle with line)
        Polygon tri = new Polygon(
                new int[]{x + 15, x + 25, x + 20},
                new int[]{y - 7, y - 7, y}, 3);
        g2.fillPolygon(tri);

        g2.setFont(new Font("Consolas", Font.BOLD, isHighRes ? 11 : 9));
        g2.setColor(isHighRes ? new Color(15, 23, 42) : new Color(226, 232, 240));
        g2.drawString(label, x + 30, y + 4);
    }

    private Point2D.Double computeSegmentIntersection(double x1, double y1, double x2, double y2,
                                                     double x3, double y3, double x4, double y4) {
        double d = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4);
        if (Math.abs(d) < 1e-6) return null;

        double t = ((x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)) / d;
        double u = -((x1 - x2) * (y1 - y3) - (y1 - y2) * (x1 - x3)) / d;

        if (t >= 0.0 && t <= 1.0 && u >= 0.0 && u <= 1.0) {
            return new Point2D.Double(x1 + t * (x2 - x1), y1 + t * (y2 - y1));
        }
        return null;
    }

    /**
     * Learn HDE Studio Dialog:
     * Interactive Step-by-Step Architectural CAD Tutorials, Modules, and Keyboard Shortcuts.
     */
